window.BC=window.BC||{};window.BC.meta={"CAISO": {"groups": ["COAL", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL": "Coal", "COAL_PRB": "Coal PRB", "COAL_BIT": "Coal Bituminous", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["NP15", "SP15", "ZP26"], "years": [2023, 2024, 2025]}, "ERCOT": {"groups": ["COAL_LIGNITE", "COAL_PRB", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["Houston", "North", "Northeast", "South", "South_Central", "West"], "years": [2023, 2024, 2025]}, "MISO": {"groups": ["COAL_LIGNITE", "COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL_LIGNITE": "Coal Lignite", "COAL_PRB": "Coal PRB", "COAL_BIT": "Coal Bituminous", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["MISO-Central", "MISO-North", "MISO-South"], "years": [2023, 2024, 2025]}, "NEISO": {"groups": ["COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL_BIT": "Coal Bituminous", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["Boston", "Central", "Connecticut", "North"], "years": [2023, 2024, 2025]}, "NYISO": {"groups": ["COAL_PRB", "COAL_BIT", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP"], "groupLabel": {"COAL_PRB": "Coal PRB", "COAL_BIT": "Coal Bituminous", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP"}, "zones": ["Capital_Hudson", "Long_Island", "NYC", "Upstate_West"], "years": [2023, 2024, 2025]}, "PJM": {"groups": ["COAL_PRB", "COAL_BIT", "COAL_WC", "CC_REGULAR", "CC_CHP", "CT_PEAKER", "CT_CHP", "ST_GAS", "ST_CHP", "OTHER_FOSSIL"], "groupLabel": {"COAL_PRB": "Coal PRB", "COAL_BIT": "Coal Bituminous", "COAL_WC": "Coal Waste", "CC_REGULAR": "CC Regular", "CC_CHP": "CC CHP", "CT_PEAKER": "CT Peaker", "CT_CHP": "CT CHP", "ST_GAS": "Steam Gas", "ST_CHP": "Steam CHP", "OTHER_FOSSIL": "Other Fossil"}, "zones": ["PJM_AEP_Ohio", "PJM_ATSI", "PJM_Central_PA", "PJM_ComEd", "PJM_Dominion", "PJM_EMAAC", "PJM_SWMAAC", "PJM_West_APS"], "years": [2023, 2024, 2025]}};window.BC.manifest=[{"id": "2026-06-17-neiso-16-ct-deploy", "label": "neiso 16 ct deploy", "date": "2026-06-17", "shorthand": "neiso-16-ct-deploy", "definition": "neiso 16 (KEEPER): neiso 14 (Merrimack COAL_BIT, keeper offer curve) + the targeted ct_deployment AS/reserve overlay, now surviving the P2 commitment screen because min_gen is carried through it (a reserve floor must survive the *economic* screen). CT_PEAKER recovers its measured sub-marginal wedge: 0.014/0.014/0.038 -> 0.084/0.052/0.079 TWh (2023/24/25). Gas total unchanged (54.78/58.89/60.14, -1.2/-1.3/+0.1% vs EIA-930) and price level unchanged (34.9/40.2/70.5 vs actual DA 36.8/41.5/67.9) -- the CT energy displaces CC within gas, NOT coal/imports (the blanket-floor failure mode). CC_REGULAR offer curve held at keeper values (the re-derived Jacobian, neiso 15, shows CC bands cannot reach CT/ST). The residual CT/ST/oil gap is the non-offer-recoverable reserve / winter-data limit.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-17-neiso-16-ct-deploy.js"}, {"id": "2026-06-17-neiso-17-mystic-cod", "label": "neiso 17 mystic cod", "date": "2026-06-17", "shorthand": "neiso-17-mystic-cod", "definition": "neiso 16 (ct_deploy keeper) + the within-window fleet-exit fix: whole plants that ran during the window and retired before the single recent EIA-860 operable vintage (2025ER) were absent from EVERY modeled year, so survivors over-dispatched to cover them. The textbook case is Mystic (plant 1588, ~1.4 GW Boston/NEMA CC, ~1.3 TWh in 2023, retired Jun 2024). Fix injects these exits from the final-vintage 'Retired and Canceled' sheets (cod_ramp + a backcast-only loader, mirror of planned additions) and caps each by its observed CEMS outages. Result: Mystic now dispatches 0.72 TWh 2023 / 0.85 TWh Jan-Jun 2024 in Boston, zero 2025; the modeled CC_REGULAR plant set differs by year (31/31/29, was 29 every year); total CC_REGULAR stays in tolerance (-0.2/-0.2/+8.7% vs EIA-923) and the run is gas-neutral (54.8/58.9/60.1) and level-neutral (34.5/39.8/70.5 vs DA 36.8/41.5/67.9) vs neiso 16. Mystic's 0.72 vs 1.31 actual is the reliability/RMR dispatch the economic LP cannot recover (same class as the CT/ST/oil wedge); 2025 +8.7% CC is the separate merit-order issue, untouched.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-17-neiso-17-mystic-cod.js"}, {"id": "2026-06-17-nyiso-7-zonal-gas", "label": "nyiso 7 zonal gas", "date": "2026-06-17", "shorthand": "nyiso-7-zonal-gas", "definition": "U4: measured per-zone gas-hub basis (NYISO SOM Figure A-6 \u2014 Upstate on Tenn Z4 200L, east on Iroquois Z2, NYC on Transco Z6 NY), shifting each gas unit vs the east reference. Plus main's year-varying Central-East TTC (2350 pre-AC-Transmission 2023 / 3850 post 2024-25). Pulls the over-priced upstate level down toward actual (2025 Upstate 75->65 vs 55.5 RT); the west-east spread is still governed by interface binding (2023 +18 overshoot, 2024-25 ~+1 undershoot vs +4-8 actual) and awaits the seasonal-TTC (U7) refinement.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-17-nyiso-7-zonal-gas.js"}, {"id": "2026-06-17-pjm-29-coopt", "label": "pjm 29 coopt", "date": "2026-06-17", "shorthand": "pjm-29-coopt", "definition": "Structure test: in-LP energy+reserve co-optimization replacing pjm_28's reduced-form reserve withholding + post-solve ORDC overlay. Per-zone reserve variable shares thermal headroom with energy (P+R<=cap); reserve balance at the measured PJM Primary Reserve requirement (backcast; 1.5x-MSSC formula for forecast) priced by the published two-step ORDC curve, so the reserve clearing price is the balance dual and lifts the energy LMP. FINDING: LMP essentially unchanged vs pjm_28 (2023 -1.1%, 2024 -7.7%, 2025 -16.8%; 2025 coal-tot +5.1% still the one fail) because PJM's ~3.4 GW reserve requirement is small vs abundant fleet headroom, so the reserve price is ~0 in nearly all hours. The LMP under-run is therefore NOT reserve opportunity cost (correcting the pjm_28 hypothesis); the co-opt is the structurally-faithful clearing mechanism (kept per claude.md #1, well-behaved -- does not over-lift the calibrated 2023) but neutral for PJM. Residual now points to the interchange gap (net under-export -24%/-46%) as the next structural lever.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-17-pjm-29-coopt.js"}, {"id": "2026-06-18-neiso-18-oil-agtdaily", "label": "neiso 18 oil agtdaily", "date": "2026-06-18", "shorthand": "neiso-18-oil-agtdaily", "definition": "neiso 18 (PROBE \u2014 partial pass; lever for 2025 CC over-dispatch). Baseline (neiso 17 mystic-cod) + --gas-hub-basis-daily: the daily within-month Algonquin Citygate basis shape (mean-preserving, demand-convex) with dual-fuel switched MWh re-attributed to oil. Targets the 2025 winter oil gap (Jan -330 / Dec -303 GWh in baseline). Result per-class TWh (model / EIA-923 %): CC_REGULAR 52.36 -0.0% / 56.37 -0.4% / 55.98 +5.4% (2023/24/25) vs baseline -0.2/-0.2/+8.7% \u2014 pulls 2025 CC down 1.77 TWh toward tolerance, 2023/24 stay in tol (no regression). oil 0.088/0.145/2.124 vs actual 0.39/0.31/0.91: recovers winter oil but OVERSHOOTS 2025 to +134% (the daily-AGT convexity, fitted not forecast-grade, builds too much oil at the 26 $/MMBtu winter spike). CT_PEAKER (-84%) and ST_GAS (-96%) unchanged \u2014 this lever does not touch the summer CT/ST wedge. Verdict: most effective single lever on the 2025 CC gap, but needs a damped basis convexity / oil-frac cap to stop the oil overshoot before it is a keeper. | CAMPD triangulation (completeness check on the +8.7% headline): on the same CEMS plant set, model/CAMPD CC = +16.6/+13.8/+19.0% (2023/24/25) and EIA-923/CAMPD = +17.9/+15.0/+9.6%. The 923-over-CAMPD premium is stable ~15-18% in 2023/24 but collapses to +9.6% in 2025 => EIA-923 CC_REGULAR 2025 is itself ~2.5 TWh UNDERCOUNTED (still filling in), not ground truth. Decompose the +8.7% (~4.6 TWh): ~2.5 TWh is 923 incompleteness, ~2 TWh is real over-dispatch (model +19% vs the ~15% CAMPD norm = the within-gas winter-oil/summer-CT-ST split). EIA-930 gas 60.1 ~= model 60.0 confirms the gas envelope is right. Real CC error ~+3-4%, not +8.7%; do not tune to the preliminary 923 bar.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-18-neiso-18-oil-agtdaily.js"}, {"id": "2026-06-18-neiso-19-ct-mustrun", "label": "neiso 19 ct mustrun", "date": "2026-06-18", "shorthand": "neiso-19-ct-mustrun", "definition": "neiso 19 (PROBE \u2014 rejected for the 2025 CC gap; informative on the CT wedge). Baseline (neiso 17) + --ct-mustrun-per-plant: forces each CT_PEAKER to its observed EIA-923 monthly net generation (the full reliability/reserve wedge, WEFOR/POF-exempt), vs baseline's sub-marginal --ct-deployment slice. CT_PEAKER TWh (model / EIA-923 %): 0.350 -15% / 0.356 -45% / 0.270 -46% (2023/24/25) vs baseline 0.084/0.052/0.079 (-80/-93/-84%) \u2014 recovers the wedge (2025 0.08->0.27; capped below 0.50 actual because the 2025 early-release 923 lists only 247 CT plants). Answers the candidate-B question: the reserve wedge (observed-energy floor) IS larger than the sub-marginal slice (cf. neiso 20 ct-deploy2x at 0.15 TWh). BUT CC_REGULAR barely moves: +8.7%->+8.4% in 2025 (-0.18 TWh, ~1:1 with the CT added) \u2014 the CT wedge is real but ~0.4 TWh, far too small to close the +4.6 TWh CC over-dispatch. ST_GAS (-95%) untouched (CT-only lever). 2023/24 CC stay in tol (-0.6/-0.7%). Verdict: correct physics, wrong magnitude for the headline gap; keep as the CT-class fix, not the CC fix.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-18-neiso-19-ct-mustrun.js"}, {"id": "2026-06-18-neiso-20-ct-deploy2x", "label": "neiso 20 ct deploy2x", "date": "2026-06-18", "shorthand": "neiso-20-ct-deploy2x", "definition": "neiso 20 (PROBE \u2014 rejected; negative control for the CT wedge). Baseline (neiso 17) + --ct-deployment-floor-frac 2.0: doubles the measured sub-marginal CT AS/RUC-deployment floor (0.08->0.15 TWh of forced energy). CT_PEAKER TWh (model / EIA-923 %): 0.113 -73% / 0.066 -90% / 0.096 -81% (2023/24/25) vs baseline 0.084/0.052/0.079 \u2014 barely moves (the sub-marginal slice is nearly exhausted at frac 1.0). CC_REGULAR unchanged at +8.7% in 2025 (-0.2/-0.3% in 2023/24, no regression, no improvement). Confirms the candidate-B contrast: the observed-energy reserve wedge (neiso 19 ct-mustrun, CT 0.27-0.36) is ~2-3x the sub-marginal deployment slice; scaling the slice is a dead end. Does nothing for the headline CC over-dispatch.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-18-neiso-20-ct-deploy2x.js"}, {"id": "2026-06-18-nyiso-10-import-node", "label": "nyiso 10 import-node-zones", "date": "2026-06-18", "shorthand": "nyiso-10-import-node", "definition": "KEEPER. U9 on top of U8 (priced interchange, nyiso 9): remaps NYISO's IMPORT_NODE_LINKS to the zones each intertie PHYSICALLY enters, measured from NYISO's hourly ExternalLimitsFlows postings, instead of the stock placement that landed imports in Capital_Hudson/Lower_Hudson (no net-import tie there). Now imports land in Upstate_West (HQ Chateauguay zone D + IESO/Ontario + PJM AC ties), NYC (PJM HTP + Linden VFT), and Long Island (PJM Neptune + ISO-NE Cross-Sound + NPX_1385); Capital_Hudson/Lower_Hudson are served across Central-East from upstate, so cheap imports can no longer bypass the interface. Restores BOTH the upstate level and the west->east spread across all years: Upstate $28.7/$35.1/$53.2 (actual 25.3/33.1/55.5); spread Cap-Up +11.4/+4.6/+4.9 (actual +9.3/+3.7/+7.9); MAE 4.81/2.03/6.77 (vs nyiso-8 10.98/2.34/3.18 and nyiso-9 3.45/1.28/7.37). Remaining residual = 2025 downstate LEVEL too low (NYC -9, LI -12): the in-city must-run / downstate-pocket structure is the next root cause, NOT the interchange.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-18-nyiso-10-import-node.js"}, {"id": "2026-06-18-nyiso-8-seasonal-ce", "label": "nyiso 8 seasonal-ce-ttc", "date": "2026-06-18", "shorthand": "nyiso-8-seasonal-ce", "definition": "U7 on top of U4: replaces the estimated annual Central-East limit (2350/3850) with the MEASURED monthly DAM TTC for the CENT EAST interface from NYISO ATC/TTC postings (~1750 MW 2023, stepping to ~2850 from Dec-2023 with the AC Transmission upgrade), applied per-hour via a seasonal envelope. Proves the interface limit, not gas basis, drives the west-east spread: 2024 MAE 7.2->2.3 and 2025 7.8->3.2 vs the no-U4/U7 baseline as the spread opens correctly (2024 +0.2->+7.1 vs actual +3.7; 2025 +0.2->+14.5 vs +7.9). But the faithful tight 2023 limit over-binds: it bottles the upstate cheap surplus and collapses Upstate to ~$6 (actual $25.3), spread +37.8 vs +9.3. Per rule #12 the measured limit STAYS; the 2023 residual localizes the next root cause = the upstate cheap-energy balance (too much trapped surplus), not the TTC.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-18-nyiso-8-seasonal-ce.js"}, {"id": "2026-06-18-nyiso-9-priced-interchange", "label": "nyiso 9 priced-interchange", "date": "2026-06-18", "shorthand": "nyiso-9-priced-interchange", "definition": "U8 (root-cause of the nyiso-8 2023 upstate collapse): serves NYISO's net imports through the PRICED import/export node (--priced-interchange) instead of folding the measured -23.5 TWh net-interchange wedge into demand by load-share. The fold deflated Upstate's true load (51.2->43.0 TWh) every hour, manufacturing a ~1760 MW surplus that over-bound the (correct, measured) Central-East limit and floored Upstate to $6 (actual $25.3); the real interface NEVER binds in 2023 (ExternalLimitsFlows: mean 1329 vs 1741 MW limit, 0% bound). With the priced node Upstate keeps its full load and imports flow only when economic: 2023 Upstate $6->$32.6 (MAE 10.98->3.45), 2024 MAE 2.34->1.28. BUT the stock IMPORT_NODE_LINKS land imports in Capital_Hudson/Lower_Hudson (which physically have no net-import tie), so cheap power bypasses Central-East and the west->east spread COLLAPSES (Cap-Up +0.1 vs actual +7.9; 2025 MAE 3.18->7.37, downstate too low). (PROBE) Root cause localized to import-node ZONE PLACEMENT -> fixed in nyiso 10.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-18-nyiso-9-priced-interchange.js"}, {"id": "2026-06-19-caiso-13-voll-ccsteam", "label": "caiso 13 voll ccsteam", "date": "2026-06-19", "shorthand": "caiso-13-voll-ccsteam", "definition": "caiso 13 voll-ccsteam \u2014 current-HEAD keeper baseline validating two fixes: (1) per-ISO VOLL load-shed cap $5,000->$2,000 (CAISO ISOConfig.voll), and (2) CC steam-turbine outage coupling (regenerated CAMPD unit-outage CSV). VOLL change is a confirmed NO-OP for CAISO: zero load-shed in all 8760h x 3yr x 4 zones, global price max $258.8 << $2,000 cap, so $5k->$2k is bit-identical. Config: --commitment --priced-interchange --hydro-backfill-year 2024 --hydro-eia930-monthly. Load-weighted RT MAE: 2024 $23.7, 2025 $23.6 (vs caiso-10 baseline 23.3 / 22.9; the +0.4/+0.8 is the CC-steam outage fix, not VOLL).", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-19-caiso-13-voll-ccsteam.js"}, {"id": "2026-06-19-neiso-21-monthly-keeper", "label": "neiso 21 monthly keeper", "date": "2026-06-19", "shorthand": "neiso-21-monthly-keeper", "definition": "neiso 21 (KEEPER \u2014 measured monthly hub-basis overlay; no fitted daily-AGT curve). Base: --commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly. CC_REGULAR (model / 923 %): 52.31 -0.1% / 56.48 -0.2% / 57.75 +8.7% (2023/24/25); 2023/24 in tolerance. RE-ANCHORED SCORING \u2014 the 2025 +8.7% is NOT a 4.6 TWh model error: (1) the gas envelope is correct \u2014 model gas 60.14 ~= EIA-930 60.09 (+0.1%), net_gen 107.28 ~= 107.15; (2) CAMPD/CEMS triangulation on the common CC plant set gives model/CAMPD = +16.7/+13.8/+19.0% (2023/24/25) and EIA-923/CAMPD = +17.9/+14.9/+10.4%. The 923/CAMPD ratio holds a stable ~+15-18% in 2023/24 but COLLAPSES to +10.4% in 2025 => the preliminary EIA-923 CC_2025 is ~2.2 TWh undercounted (still filling in), not ground truth. Decompose the +8.7% (~4.6 TWh over 923): ~2.2 TWh is 923 incompleteness, ~2 TWh is a small within-gas over-dispatch (model +19% vs its ~+15% CAMPD norm). Real CC error ~+3-4%, NOT +8.7%; the residual %-gap is benchmark incompleteness, not model error \u2014 do not tune CC down to the 53.1 preliminary-923 bar. The fitted --gas-hub-basis-daily daily-AGT overlay was REJECTED this session: its convexity is fitted to the backcast and tuning it to hit EIA-930 oil is curve-fitting a magic number, so the keeper stays on the measured monthly overlay.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-19-neiso-21-monthly-keeper.js"}, {"id": "2026-06-19-neiso-22-ccsteam-keeper", "label": "neiso 22 ccsteam keeper", "date": "2026-06-19", "shorthand": "neiso-22-ccsteam-keeper", "definition": "neiso 22 (KEEPER \u2014 supersedes neiso 21). Re-ran the monthly-keeper config (--commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly) to integrate the combined-cycle steam-turbine unit-outage derate (eia_*_cc capacity coupling in campd-unit-outages-NEISO.csv; derivation-script level, NO magic numbers \u2014 the fitted daily-AGT convexity stays rejected), and fixed a poisoned gas-basis cell. VERDICT: NEISO is backcast-calibrated. CC_REGULAR 52.30/56.51/57.76 reproduces the keeper (52.31/56.48/57.75) within +/-0.03 TWh; gas within ~1% of EIA-930 all years (54.76/58.87/60.11 vs 55.47/59.64/60.09); LW hub $35.08/$40.52/$71.20 vs actual DA $36.82/$41.47/$67.86 (-4.7/-2.3/+4.9%); the 2025 monthly DA shape tracks actual within a few $/MWh every month. The CC-steam derate is a NEAR-NO-OP for NEISO \u2014 controlled A/B (only the outage CSV swapped) moves 2025 CC_REGULAR -0.02 TWh and LW price +$0.9; the fleet has the headroom to absorb it (adopt for cross-ISO consistency). SEPARATELY FIXED (commit aa62655): the 15:46 fetch-eia-gas-prices refresh (postdates neiso 21) wrote a +$13.46/MMBtu Aug-2025 AGT basis from the EIA MA citygate proxy \u2014 a winter-level summer-month LDC citygate average that drove modeled Aug-2025 LMP to $167 vs the actual $45.6 DA; replaced with the Jul/Sep interpolation (+0.04). Before a forecast run: the neighbor-convexity priced-import node is REQUIRED (the seam is a fixed measured schedule today), plus the derived daily-AGT winter-oil convexity when upload U4 lands (oil 0.00/0.00/0.06 vs EIA-930 0.32/0.37/1.24, LMP-neutral). Full diagnosis: results/calibration/DIAGNOSIS-neiso-ccsteam-2026-06-19.md; forecast-prep prompts: docs/multi-iso/neiso-forecast-prep-prompts.md. SYSTEM VOLUME ERROR FIX (render_calibration_html, incomplete-vintage benchmark repair): the 2025 fossil benchmark was raw preliminary EIA-923, under-counting CC by ~4 TWh (CC bench 53.12 vs model 57.76, which matches complete EIA-930 within 1%), inflating the 2025 system volume error to +7.25%. The benchmark now scales any fossil fuel whose grid 923 total is <0.97x the complete EIA-930 grid series up to that EIA-930 total (split/shape preserved); 2025 sys vol err +7.25% -> ~0%, complete vintages (2023 1.02x / 2024 1.02x) untouched. CEMS audit confirmed CEMS under-reads CC every year (44-49 vs 923's 52-57) so it is a shape source, not a level authority; the model is correct.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-19-neiso-22-ccsteam-keeper.js"}, {"id": "2026-06-19-nyiso-11-cc-steam", "label": "nyiso 11 cc-steam rebaseline", "date": "2026-06-19", "shorthand": "nyiso-11-cc-steam", "definition": "BASELINE re-established on current main, same keeper config as nyiso 10 (priced interchange + U9 import-node zone remap, gas_monthly_actuals, commitment), after two main fixes landed: (a) load-shed now prices at each ISO's own VOLL (NYISO $2,000, not ERCOT $5,000), (b) the CC steam-turbine outage-coupling fix (9988a79) regenerated campd-unit-outages-NYISO.csv so a combined-cycle CT derates its steam-augmented block when it trips. Effect on the CC-heavy NY stack: CC backs down ~1.7 TWh in 2023 (CC_REGULAR 29.2->28.5, CC_CHP 13.6->12.7), backfilled by imports (16.4->17.9 TWh), gas total 65.1->63.5. Fuel-mix bands HOLD: 2023 vs EIA-923 gas -0.5%, nuclear -0.1%, hydro -0.1% (at 28.40 TWh budget), wind exact; 2025 on the EIA-930 operational basis (EIA-923 2025 is the incomplete prelim M-file) gas -6.4%, nuclear -0.1%, hydro at budget. Price MAE (demand-wtd monthly LMP vs actual RT) 8.20/4.74/5.98 for 2023/24/25 -- essentially unchanged vs nyiso 10 recomputed on the same metric (7.90/4.52/6.23; +0.30/+0.22/-0.25), and the residual SHAPE is identical: 2023 over-prices winter/shoulder (Jan +45, Feb +12, Mar +13), 2025 under-prices the summer/winter downstate tail (Jan -11, Feb -14, Jun -10, Jul -10). Firm-load shed 0 zone-hours all years; zonal pmax 342/198/270. The outage fix is measured ground truth and was NOT tuned around. DIAGNOSIS of the remaining residual (post-solve, no params changed): it is gated by IMPORT-NODE DISCIPLINE, not the outage derate and not CC mispricing. NYC thermal availability is flat across years (5,891 vs 5,782 MW avg, 2023 even higher) and dispatch never exceeds availability (0 capacity-pinned / 0 negative-headroom hours), so the derate did not reduce NYC capacity. The driver is the priced import node: 2023 UNDER-imports (-17.9 vs measured -23.5 TWh, capped ~3.3 GW vs actual 4.9), so NYC backfills with peakers (gas_ct 2,741 vs 1,401 GWh) and -- with the ~1,000 MW NYC interface (HTP+Linden) binding in 200/200 tight summer hours where the import-node price ($33) sits $30 below NYC ($63) -- the energy LP ALREADY prices that downstate congestion; 2025 OVER-imports (-21.9 vs -19.1, diurnal corr -0.86) so NYC under-separates. The locational RCPF overlay (NYISO_RCPF_LOCATIONAL) is structurally correct NYISO market design (tariff-sourced RS4/FERC ER21-502, nested NYCA/East/SENY/NYC reserve demand curves) and stays as-is, but it is GATED ON the energy LP's headroom, which is contaminated by this import-node dispatch error -- so it over-fires in 2023 (NYC $64/yr, Jul $206; would double-count the congestion already in LBMP) and under-fires in 2025. The structural next step is import-node discipline (per-year neighbor-price ladder re-anchor + finer import duration tranches), with the interchange duration band and gas volume as guardrails -- NOT RCPF tuning, which is correct and merely waiting on the upstream physics.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-19-nyiso-11-cc-steam.js"}, {"id": "2026-06-19-pjm-32-refconvex", "label": "pjm 32 refconvex", "date": "2026-06-19", "shorthand": "pjm-32-refconvex", "definition": "(PROBE - structural diagnostic, NOT a keeper). pjm_28 keeper config but the interchange seam is served by the forecast-grade REFERENCE-PRICE interface (replaces the fitted, per-year EXPORT_TRANCHES with each neighbor priced (HenryHub+basis) x marginal_HR x (load/mean)^exp) PLUS neighbor price-vs-load CONVEXITY load_shape_exponent=1.63 - self-derived from NYISO's own realized RT LMP (log-LMP on log-load, R2 0.36, stable 1.64/1.63 by year), adopted for MISO/Carolinas as the organized-thermal-neighbor value (cross-validated NEISO 2.04 / ERCOT-net 1.47) pending their own-LMP fetch. Nothing tuned to PJM's net-MWh (claude.md #11). RESULT: the seam LIFTS energy LMP toward actual every year - 2023 -1.1%->+4.0% (29.57 vs 28.44), 2024 -7.7%->-4.1% (28.32 vs 29.53), 2025 -16.8%->-10.5% (38.40 vs 42.89) - confirming the missing summer-afternoon $75-200 regime was peak-coincident export tightening. BUT the convexity self-limits the over-export only partway (pjm_31 +78 -> +62 TWh in 2023): net export flips from pjm_28's UNDER (-46/-24/-46%) to OVER (+56/+34/+112%, actual 40.0/32.7/18.0), and the excess export over-generates fossil (gas 2024 +6.9% / 2025 +7.0% FAIL; coal-tot 2023 +9.4% / 2025 +9.5% FAIL; 7 in-tol fails vs pjm_28's 0). 2025 is worst (+112%): the single 2023-24 neighbor HR anchors miss 2025's collapsed PJM-neighbor spread. NEXT LEVER (data-driven, no fit): (1) fetch MISO Indiana-Hub + Duke LMP -> derive each dominant seam's OWN convexity (likely steeper than NYISO's 1.63, self-limiting more); (2) year-grounded neighbor HR anchor from each neighbor's own per-year realized-LMP/gas ratio to compress the 2025 spread. pjm_28 stays the keeper until the over-export is bounded by these.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-19-pjm-32-refconvex.js"}, {"id": "2026-06-19-pjm-33-miso-reanchor", "label": "pjm 33 miso reanchor", "date": "2026-06-19", "shorthand": "pjm-33-miso-reanchor", "definition": "Forecast-grade reference-price interchange seam (pjm_32 lineage) with the dominant MISO seam now anchored entirely to MISO's OWN measured Indiana-Hub RT LMP (fetched from docs.misoenergy.org), replacing estimates (claude.md #12): marginal heat rate 14.2->12.9 (14.2 used the IMM ~$36 all-footprint average; the border Indiana Hub measures $31.8/$30.8/$42.85 = LMP/HH 12.5/14.1/12.2, mean 12.9 -> 14.2 over-priced the border by +13%/+17% in 2023/2025) and convexity 1.63->1.60 (self-derived, R2 0.24 -- confirms the borrow was sound, so convexity was NOT the over-export driver; the level was). derive_neighbor_convexity --check now guards both. RESULT vs pjm_32: net export corrects toward measured every year -- 2024 +34%->+1.8% (33.3 vs 32.7 TWh, near-perfect), 2025 +112%->+30% (23.4 vs 18.0), 2023 +56%->+32% (52.7 vs 40.0); in-tol fails 7->5; 2024 now fully passes (coal-tot +1.0%, gas +4.8%). HONEST TRADE-OFF: with interchange correctly sized the LMP under-run is no longer masked by over-export -- 2025 LMP -13.7% (was pjm_32 -10.5%, pjm_28 -16.8%), 2024 -6.4%, 2023 +2.1% -- revealing the residual under-run is PJM's OWN price-formation gap (scarcity/congestion/reserve adders the energy-only LP omits), NOT interchange. Residual coal-over in 2023/2025 (+7%) is the forecast-native single MISO HR (12.9) slightly over-pricing those years (their measured ratios 12.5/12.2 < 12.9); a per-year HR would close it but isn't forecastable. Most structurally faithful PJM run to date (every seam parameter measured from the neighbor's own data, nothing tuned to PJM flow, rule #11); pjm_28 remains the lowest-fail FITTED reference.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-19-pjm-33-miso-reanchor.js"}, {"id": "2026-06-19-pjm-34-coal-rank", "label": "pjm 34 coal rank", "date": "2026-06-19", "shorthand": "pjm-34-coal-rank", "definition": "pjm_33 lineage (forecast-grade reference-price interchange seam, MISO reanchor) + a CORRECTNESS fix to coal-rank labeling: three retiring PJM coal plants \u2014 W H Sammis (OH), Homer City (PA), AES Warrior Run (MD), all bituminous \u2014 were stuck in the model's generic unranked COAL bucket because coal_supply_class consulted only the curated + EIA-923 fuel-receipt maps, and a mid-backcast retiree has no recent burned-fuel receipts to derive a rank from. The EIA-923 benchmark already resolves them to COAL_BIT via fuel code, so the model showed a spurious generic 'Coal' row the actual never has AND priced them at generic full cost instead of PJM's bituminous passthrough. FIX (data.fleet.coal_supply_class): a tertiary EIA-860 energy_source fallback scoped to the retired-within-window vintage (the exact structural gap; operable coal untouched), mirroring the benchmark's fuel-code fallback. PJM coal now fully resolves (32 bituminous, 0 unranked); 212 fleet/coal tests pass. KEY FINDING \u2014 the dashboard's '+7%' 2023 coal-over was a LABELING ARTIFACT: the coal-tot gate sums only BIT+PRB+WC, so it compared model-coal-MINUS-the-3-retirees (~13 TWh hidden in the excluded generic bucket) against actual-coal-that-INCLUDES-them. Apples-to-apples the 2023 coal-over is +18.7% (+21 TWh), not +7%; total model coal barely moved (136.7->134.8 TWh, repricing ~dispatch-neutral) \u2014 only the attribution became honest. SCORECARD vs actual (coal-tot %; LMP %): 2023 coal-tot +18.7% (was +6.9%), COAL_BIT +20.0%, gas +2.2%, LMP +2.4%, net-export +29.6% | 2024 coal-tot +3.9% (was +1.0%, still PASS, 0 fails), LMP -6.3% | 2025 coal-tot +7.5% (UNCHANGED from pjm_33 \u2014 no retirees operating, so this is the GENUINE coal-over, not labeling), LMP -13.7%. in-tol fails 5 (same count as pjm_33; 2023 COAL_BIT/coal-tot, 2025 COAL_BIT/COAL_PRB/coal-tot). ROOT CAUSE now visible: ~half the 2023 coal-over is the 3 retirees over-dispatching (Homer City model 9.1 vs 1.0 TWh actual) \u2014 part a COD-ramp partial-retirement bug (load_cod_map collapses heterogeneous unit-retirement dates to the latest, so Homer City runs 2 units that retired Jul/Aug through year-end; small-scope 4-plant cross-ISO fix deferred), part the dominant economic over-dispatch of cheap uneconomic retirees the energy-only LP runs as baseload (needs CAMPD unit-level availability, not a fit). LMP/interchange unchanged vs pjm_33; this run makes the coal scorecard HONEST (faithfulness over MAE) and supersedes pjm_33's misleading coal-over.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-19-pjm-34-coal-rank.js"}, {"id": "2026-06-19-pjm-35-cc-steam", "label": "pjm 35 cc-steam rebaseline", "date": "2026-06-19", "shorthand": "pjm-35-cc-steam", "definition": "KEEPER. Re-baseline of the pjm_34 recipe (pjm_28 config + forecast-grade reference-price interchange seam + neighbor price-vs-load convexity) on the CC steam-turbine outage coupling now in main: a CC's CT outage derates its full block (CT + the steam it fed) instead of the CT alone, so the steam is no longer phantom-available during CT outages. Nothing tuned to PJM's net-MWh/price residual. Coal-tot over: 2023 +15.7% (was pjm_34 +18.7%), 2024 +5.0% (+3.9%), 2025 +8.7% (+7.5%); gas in tolerance all years (+1.4/+3.6/+3.0%). FINDING: the bituminous 0.76 passthrough floor is NOT the coal-over lever \u2014 2025 has zero retirees yet COAL_BIT overs +7.8% at a ~1.08 passthrough (near full fuel cost, $3.52 gas ~ gas_mid 3.40), and the over runs INVERSE to the cheap-gas discount (2024 deepest discount 0.79 -> smallest over). Residual coal-over is structural (operable-coal baseload + 2023/24 retiree over-dispatch: Homer City/Sammis/Warrior Run 6.25 TWh in 2023, 3.2 in 2024, 0 in 2025), addressable only by measured COD fractional-retirement + CAMPD unit availability, not by tuning the passthrough.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-19-pjm-35-cc-steam.js"}, {"id": "2026-06-20-nyiso-12-interchange-shaping", "label": "nyiso 12 interchange-shaping", "date": "2026-06-20", "shorthand": "nyiso-12-interchange-shaping", "definition": "(PROBE \u2014 REJECTED.) Mechanism-A test on the nyiso 11 keeper config: adds --interchange-shaping, which caps each priced import tranche's availability by the MEASURED EIA-930 month x hour-of-day p90 net-import envelope (no fitted constant) to fix the static node's flat-schedule diurnal defect. It DOES fix the shape (net-import hour-of-day corr vs measured 2023 +0.69->+0.96, 2025 -0.86->+0.24), confirming the 2025 over-import/diurnal-mis-shape diagnosis is real. BUT the p90 net-import cap is tighter than the keeper's flat economic clearing in most buckets, so it starves baseload imports: net interchange falls to 60.6/74.9/71.6% of measured (2024 & 2025 go from in-band to OUT of the +/-15% interchange band), in-state gas rises (2025 -6.4%->+5.0% vs EIA-930), and the demand-weighted monthly LMP MAE WORSENS every year (8.0/4.3/6.3 -> 9.6/7.5/8.3). Per the volume-band guardrail (a shape gain bought by breaking a volume band is a zero-sum trade -> report and stop), REJECTED; keeper nyiso 11 stands. The off-the-shelf shaping is CAISO-shaped (gross-import cap to a net envelope); the right NYISO tool is a firm/baseload must-flow tranche or a level-preserving diurnal re-weight (see docs/nyiso-backcast-residual-attribution-2026-06.md).", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-20-nyiso-12-interchange-shaping.js"}, {"id": "2026-06-20-pjm-36-retiree-cems", "label": "pjm 36 retiree cems", "date": "2026-06-20", "shorthand": "pjm-36-retiree-cems", "definition": "NEW KEEPER (supersedes pjm 35 cc-steam). pjm_35 config + within-window retiree CEMS measured-availability cap (retiree_cems_cap=True): each within-window retiree plant is limited to its measured monthly CAMPD CEMS envelope (zero in months it did not run), honestly reflecting the out-of-market retirement economics a cost-based LP cannot see \u2014 nothing tuned to the coal/net-MWh target. Closes the Homer City (3122) phantom-baseload over: model 4.40/2.79/0.00 \u2192 1.48/0.00/0.00 TWh vs CEMS 1.20/0.00/0.00. Two compounding fixes: (a) per-unit COD retirement in cod_ramp (effective_cod no longer collapses heterogeneous unit retirements to the latest date) \u2014 MAE-neutral alone, the per-plant binning merges units before the ramp; (b) the CEMS cap, which moves the aggregate. Coal-tot: 2023 +15.7%\u2192+13.8%, 2024 +5.0%\u2192+3.1% (now PASS), 2025 +8.7% unchanged (no running retirees \u2014 clean blast radius). In-tolerance fails 7\u21925; freed retiree energy split between gas (stays PASS) and reduced 2023 over-export (interchg +15.0%\u2192+11.6%). Finding: the residual operable-coal over (2025 +7.8% BIT, confound-free) is system merit-order, NOT a retiree-capacity issue.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-20-pjm-36-retiree-cems.js"}, {"id": "2026-06-21-caiso-18-outage-regate", "label": "caiso 18 outage regate", "date": "2026-06-21", "shorthand": "caiso-18-outage-regate", "definition": "Outage re-gate of the caiso-15 all-flags keeper (commitment, priced-interchange, 2024 hydro repin + EIA-930 monthly, gas-hub-basis overlay, import gas-coupling + solar-shape) on the net-load-filtered CAMPD unit-outage CSV (commit b0c41cb; CAISO outage GW-days -37%). ONLY the outage input changed vs caiso-15; byte-faithful re-solve from run_config.json. RESULT (2024): body COOLS mean 42.00->41.17 (resid +6.15->+5.32), p50 46.80->46.34, p95 63.73->62.96; negative tail PRESERVED (neg 407->408 @ 91.9% precision, recall 49.5->49.7%). Cooling is localized OVERNIGHT (h00-04 each ~-1.1: more available CC lowers the gas-set price) - the gas-bound +44% block in DIAGNOSIS-caiso-body-overprice; midday import floor (h10-14, ~+12.5) and the under-priced evening ramp are UNCHANGED (orthogonal to outages, as predicted). FUEL MIX: gas +4%->+5% vs EIA-923 (71.07->71.85 TWh); the re-gate slightly WORSENS the CC-over/peaker-under split (CC_REGULAR 51.85->53.03, CT_PEAKER 0.16->0.03, ST_GAS 3.19->2.76) - fewer outages let commitment lean even harder on CC, confirming the mix defect is a COMMITMENT/merit-order property, not an availability one (TASK-2 hypothesis 1). Clean LMP win; mix defect is a separate commitment issue. | BTM RE-SCORE (2026-06-22): re-solved byte-faithfully (gmModel reproduces the keeper exactly, CC_REGULAR 53.03/CC_CHP 9.39) and added btm.parquet (CC_CHP 4.26 / CT_CHP 1.77 TWh BTM host steam). CC_CHP residual -7.07->-2.82 TWh (and +0.48 PASS vs raw EIA-923-BTM): the over-statement WAS the BTM artifact. DETERMINATION: NOT-YET. C2 gas -15.8% vs the authoritative EIA-930 grid total (CAISO EIA-923 under-reports gas ~25%: raw923 68.3, 923-BTM 62.3, e930 85.4) and the CC-over/CT-under merit split are genuine MODEL MISSes (doc 06 structural midday-import/solar-glut wedge), not ledgerable. C6 governance now PASS (attestation added).", "years": [2024], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-21-caiso-18-outage-regate.js"}, {"id": "2026-06-21-neiso-23-outage-btm", "label": "neiso 23 outage-btm-basis", "date": "2026-06-21", "shorthand": "neiso-23-outage-btm", "definition": "neiso 23 (KEEPER \u2014 supersedes neiso 22). Two folded, independently-attributable changes re-solved in one byte-faithful pass off the neiso-22 run_config (scripts/run_calibration_full.py --iso NEISO --year 2023 2024 2025 --commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly; gas-hub-basis monthly overlay on by default). TASK A \u2014 OUTAGE RE-GATE (model-side): swapped in the net-load-filtered (revealed-availability) data/raw/campd-unit-outages-NEISO.csv (branch claude/ercot-scarcity-tuning-handoff-nl1y3m @ b0c41cb), capacity-weighted outage GW-days 6150->4049 (-34%; summer binding preserved, shoulder/winter economic-idle mass cut). Everything else identical -> the dispatch/system/storage parquets are the pure outage delta. Near-no-op on dispatch, as expected from the keeper's headroom: CC_REGULAR 52.34/56.54/57.89 TWh (keeper 52.31/56.48/57.75; +0.03/+0.06/+0.14). Cooler shoulder/winter LMP, the expected revealed-availability direction: load-wtd hub $34.06/$39.00/$69.60 (keeper $35.08/$40.52/$71.20; vs actual DA $36.82/$41.47/$67.86 -> -7.5%/-6.0%/+2.6%, was -4.7/-2.3/+4.9%). FLAG: 2023/24 now run ~6-7.5% below actual DA (a ~$1-1.5 cooling) \u2014 modest, not an under-fire; summer/tail preserved (zone-avg hrs>$200: 0/0/13). TASK B \u2014 CHP BTM BASIS FIX (benchmark-side; solve-invariant): the grid LP holds out behind-the-meter CHP host self-supply for ALL ISOs, so gmModel is grid-delivered only, but btm.parquet was written ERCOT-only (run_calibration_full.py gated btm_frames.append on is_ercot). NEISO render fell back to FULL EIA-923 (BTM included) vs a grid-only model -> a false ~1.3 TWh/yr CHP shortfall (~60% of the prior -3.8/-4.1% 2023/24 system volume error). FIX: removed the is_ercot gate so _btm_frame runs for every ISO, building the per-plant CHP bin frame from the year's EIA-860 fleet group map (the non-ERCOT analogue of the curated CAMPD bin sheet) instead of the ERCOT-only sheet; plant codes parsed numeric-head like the dispatch frame. btm.parquet CHP btm_twh now present: CC_CHP 0.58/0.66/0.52, CT_CHP 0.56/0.53/0.13, ST_CHP ~0 (model slightly over-produces ST_CHP, so 923-grid clips to 0 \u2014 within abs band, not chased). classFull = EIA-923 - per-class BTM now lands on gmModel: CC_CHP 1.35/1.36/1.48 vs model 1.36/1.35/1.44 (|d|<=0.04, in tolerance all 3 yrs); CT_CHP (gate-excluded) 1.04/1.03/0.33, within +/-1 TWh abs. SYSTEM GAS VOLUME ERROR 2023 -1.3% / 2024 -1.6% / 2025 +0.4% (down from -3.8/-4.1% on the false full-923 basis; CC_REGULAR -0.04%/-0.13%/+0.75% vs classFull). 2025 stays ~0% anchored by the EIA-930 incomplete-vintage reconcile (render _VINTAGE_RECONCILE_FRAC=0.97; gas scaled x1.082, complete 2023/24 untouched at 1.001/1.005); the uniform reconcile re-inflates 2025 CC_CHP classFull 1.36->1.48 but model 1.44 still sits inside tolerance, so no CC_REGULAR-concentration override was needed. Fixing at the source (btm.parquet) keeps render, session_score, compare_runs_classes and the offer-curve Jacobian on the same grid-delivered basis. The remaining ~0.8 TWh of the 2023 system gap is small peaker/steam classes the model zeroes (CT_PEAKER, ST_GAS, COAL_BIT) \u2014 real tiny dispatch differences within +/-1 TWh abs, NOT a reporting artifact; not conflated with the BTM basis. FOLLOW-UP (out of scope here): the same BTM gate fix will correctly affect the PJM/CAISO/NYISO keepers once their bundles regenerate btm.parquet \u2014 re-register those later. Carries forward all neiso-22 forecast-prep caveats (priced-import seam node REQUIRED before a forecast run; daily-AGT winter-oil convexity stays rejected as curve-fitting). Full neiso-22 diagnosis: results/calibration/DIAGNOSIS-neiso-ccsteam-2026-06-19.md.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-21-neiso-23-outage-btm.js"}, {"id": "2026-06-21-nyiso-13-citygate-gas", "label": "nyiso 13 citygate-gas", "date": "2026-06-21", "shorthand": "nyiso-13-citygate-gas", "definition": "(PROBE \u2014 REJECTED.) Mechanism-D test on the nyiso 11 keeper: --gas-hub-basis-overlay replaces the EIA-923 monthly gas RECEIPT series (winter-inflated; Jan-2023 $10.02/MMBtu, a Winter-Storm-Elliott billing artifact) with the monthly EIA NY-CITYGATE level already in the repo (Henry Hub + N3050NY3 basis, gas_basis_by_iso_month.csv), zonal spread + dual-fuel cap applied on top. It FIXES the winter (Jan resid +44->+14, CC fuel $39 vs actual $38; Feb held) -- confirming the winter over-price is a gas-series artifact, not scarcity -- but the EIA N3050NY3 'citygate' is an LDC/utility delivered price carrying summer demand charges, NOT the power-plant marginal spot, so it OVER-states summer by ~$10-13/MWh (Jul citygate $6.6 -> CC $46 vs actual $36; resid Jul +4->+46, Aug +2->+42). Net: monthly LMP MAE WORSENS 8.0/4.3/6.3 -> 21.5/22.2/24.2 and gas falls out of the +/-5% band (2023 -0.5%->-9.4% vs EIA-923; 2025 -6.4%->-13.4% vs EIA-930). 2023 net interchange incidentally improves to 97% (in band). REJECTED per the volume-band + don't-trade-one-axis-for-another guardrail; keeper nyiso 11 stands. The receipts (winter-high) and EIA citygate (summer-high) monthly proxies BRACKET the truth; the clean fix is a Transco-Z6 NY / Iroquois Z2 trading-hub SPOT series, distinct from both. See docs/nyiso-backcast-residual-attribution-2026-06.md.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-21-nyiso-13-citygate-gas.js"}, {"id": "2026-06-21-nyiso-14-som-anchored", "label": "nyiso 14 som-anchored-gas", "date": "2026-06-21", "shorthand": "nyiso-14-som-anchored", "definition": "(PROBE \u2014 confirms the mechanism-D diagnosis but not a clean fix.) Third gas-series test, built from ONLY sourced data after the 'isn't the monthly citygate already in the repo?' question: gas level = Henry Hub MONTHLY shape (EIA RNGWHHDm) re-levelled to the NYISO State-of-the-Market MARGINAL-hub ANNUAL value (nyiso_zonal_gas_hub.csv, Iroquois Z2 at the Capital reference), zonal basis spreading the rest; replaces both the winter-high EIA-923 receipts and the summer-high EIA citygate. RESULT: Jan-2023 residual collapses +44 -> +4 (gas vs EIA-923 -0.5%->-2.8%, in band) -- PROVING the 2023 winter over-price is the gas series, not scarcity. BUT the SOM anchor is ANNUAL-only: a flat annual level x Henry Hub's near-flat monthly shape cannot reproduce a winter-weighted hub, so non-winter months over-level (+~10/mo) and 2025 -- whose SOM annual $6.02 is dominated by the Jan cold-snap blowout -- smears across summer and explodes. Monthly LMP MAE 8.0/4.3/6.3 -> 9.3/9.0/18.7 (net worse); rejected. Decisive finding: the repo's receipts (winter-high), EIA citygate (summer-high, an LDC $/Mcf series that PEAKS in summer), and annual SOM hub BRACKET the truth but none is it; the clean fix needs the MONTHLY (or daily) Transco-Z6 NY / Iroquois-Z2 trading-hub SPOT (NGI/ICE/Platts or NYISO reference-level), which EIA does not publish free. See docs/nyiso-backcast-residual-attribution-2026-06.md.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-21-nyiso-14-som-anchored.js"}, {"id": "2026-06-21-nyiso-15-transco-z6", "label": "nyiso 15 transco z6", "date": "2026-06-21", "shorthand": "nyiso-15-transco-z6", "definition": "Mechanism-D gas fix: keeper + --gas-hub-basis-overlay with the NYISO basis rebuilt from the REAL monthly EIA NG Weekly Transco Z6 NY spot ('New York'), lifted to the Iroquois Z2 reference level by the SOM annual inter-hub spread; zonal basis spreads NYC back to Transco. Fixes the dominant Jan-2023 winter artifact (resid +44 -> +7.4; 2023 monthly-LMP MAE 8.0 -> 5.6); 2024/25 MAE 5.9/7.5 and 2025 net-interchange 117.5%. Monthly mean still smears extreme-cold months (Jan-2025 +39) -> next is DAILY Transco resolution + a real monthly Iroquois. | BTM RE-SCORE (2026-06-22): byte-faithful re-solve (gmModel reproduces the keeper to <0.1%) + btm.parquet (CC_CHP 3.3-4.8/CT_CHP/ST_CHP TWh) -> CHP scored grid-delivered; 2024 CC_CHP clears (was -2.93). C6 governance PASS (attestation). DETERMINATION: NOT-YET. Deciding fails are MODEL MISSes (not ledgerable): CC_REGULAR -7.1/-13.3/-7.9% under-dispatch (no BTM; gas-basis/interchange merit), gas family +5.4/-10.6/-7.3%, ST_GAS +-2-4 TWh; 2023/25 CC_CHP +2.3/+2.9 over their measured 923 grid output.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-21-nyiso-15-transco-z6.js"}, {"id": "2026-06-21-pjm-38-outage-regate", "label": "pjm 38 outage regate", "date": "2026-06-21", "shorthand": "pjm-38-outage-regate", "definition": "NEW KEEPER (supersedes pjm 36 retiree-cems). The pjm 36 keeper config (retiree_cems_cap=True) re-solved byte-faithfully on the net-load-filtered outages (commit b0c41cb), changing ONLY the outage input \u2014 the cross-ISO revealed-availability filter that cut PJM capacity-weighted outage GW-days ~46% (concentrated Apr/Oct, summer preserved). Promoted under right-structure-first: the net-load filter is the forecast-defensible exogenous outage input (keys on net load, not price). Honest gate result (NOT clean \u2014 accepted as forecast-native, see docs/multi-iso/pjm-outage-regate-2026-06.md): the cooler shoulder/winter availability lets the cost-based LP run the freed cheap take-or-pay coal/CC, amplifying PJM's documented forecast-native coal over-run + over-export. Coal-tot resid 2023 +6.8->+17.3%, 2024 -2.2->+13.9%, 2025 +2.4->+22.8%; net-export +11.6->+69% / -11.8->+65% / +28->+204%; in-tolerance fails 3->11. LMP cools further below actual (load-wtd mean 30.09->28.12 / 28.06->26.17 / 37.81->34.63; lwt-MAE 8.30->8.12 / 10.46->10.49 / 15.06->15.82; hrs>$200 0/0/0 unchanged). The coal-over/export is the next frontier (offer-curve / coal-cost retune), not chased here. | BTM RE-SCORE / FIRST REGISTRATION (2026-06-22): pjm_38 was a stub (no payload); re-solved its committed keeper config from meta.json, writing btm.parquet + full payload + bench. C6 governance PASS (attestation). DETERMINATION: NOT-YET. Deciding fails are MODEL MISSes (not ledgerable): C2 coal +17.3/+13.9/+22.8% (the documented PJM structural coal over-run, a SEPARATE issue amplified by the net-load re-gate, not folded in here), CT_PEAKER -18/-33% under, CC_CHP +1-2 over measured 923 grid, C3a LMP -11.4/-19.3% (2024/25). C4 PASS.", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-21-pjm-38-outage-regate.js"}, {"id": "2026-06-21-run143-keeper-net-load", "label": "run143 KEEPER net-load outage filter", "date": "2026-06-21", "shorthand": "run143-keeper-net-load", "definition": "(SUPERSEDED by run144, the local-seasonal-band re-solve \u2014 run144 gated CLEAN vs this run, mean monthly MAE 8.2->7.7.) KEEPER (supersedes run142). Same two grounded fixes as run142 \u2014 the CAMPD revealed-availability outage filter (drop economic-idle false outages that the CF<5% rule flagged in low-demand months, the source of the 2024/25 co-opt over-fire) + the ST_GAS committed-offer restore \u2014 but the filter now keys on EXOGENOUS NET LOAD (EIA-930 demand-wind-solar) instead of raw load, to also catch winter-storm/VRE-drought tightness below the summer raw-load peak. Result: 2023 36.5/MAE 12.0/tail 104-56; 2024 23.2/MAE 9.6/22-16; 2025 31.4/MAE 2.9/1-0 vs actual 48.4(181/104)/26.8(53/16)/32.5(31/3). Mean MAE 8.2 (run139 keeper was 10.6). Over-fire fixed (Oct-2024 $73.7/17h -> $32.3/3h) with real summer scarcity preserved (Aug max $5000). FINDING: net-load == load-p85 (run142, mean MAE 7.7) within noise; net load did NOT recover the 2024-Jan winter storm ($22/3h vs actual $44/19h) \u2014 winter-storm scarcity is a separate extreme-weather/out-of-market problem, like 2023's ~42% out-of-market tail (run140), not an outage-filter lever. KNOWN: tails still thin (under actual scarcity-hour counts); 2023 structurally under. GATED: ERCOT outage CSVs regenerated on net-load; OTHER ISOs share the rule and need re-gating by their owners.", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-21-run143-keeper-net-load.js"}, {"id": "2026-06-22-caiso-19-local-band", "label": "caiso 19 local band", "date": "2026-06-22", "shorthand": "caiso-19-local-band", "definition": "caiso 19 local-band outage regate (correct forward input; supersedes caiso 18). The caiso-15/18 all-flags keeper config (--commitment --priced-interchange --hydro-backfill-year 2024 --hydro-eia930-monthly --gas-hub-basis-overlay --caiso-import-gas-coupling --caiso-import-solar-shape) re-solved BYTE-FAITHFULLY on the LOCAL (seasonal) net-load outage band \u2014 high_load_mask centered rolling +/-30d window (commit 152bb99) instead of the single annual percentile, recovering genuine multi-week shoulder maintenance outages. ONLY the outage input changed vs caiso 18 (regenerated data/raw/campd-unit-outages-CAISO.csv, auto picked up). 2024 RESULT vs caiso-18 (annual band): the recovered shoulder outages put slightly LESS CC availability in, so the gas-set overnight block FIRMS marginally \u2014 body mean 41.17->41.45 (+0.28), p50 46.34->46.23, p95 62.96->63.45; the negative midday tail is PRESERVED (neg 407 vs 408) and there is NO scarcity over-fire (model hrs>$200 = 0, max $69.64). The +0.28 firming is the genuine outage physics on the gas body, NOT a scarcity over-fire; the midday import floor (h10-14) and evening-ramp underprice are UNCHANGED (orthogonal to outages, as caiso-18 predicted). FUEL MIX marginally IMPROVES the documented CC-over split: CC_REGULAR 53.03->52.68 (fewer outages had let commitment lean harder on CC; recovering them trims it), CT_PEAKER 0.03->0.05, ST_GAS 2.76->2.73 - confirming the mix defect is a COMMITMENT/merit-order property, not an availability one. Net a wash on LMP with a marginally better mix, on the correct exogenous outage input (keys on net load, not price). The body/midday overprice remains CAISO's documented SEPARATE commitment issue (DIAGNOSIS-caiso-body-overprice), neither introduced nor fixed here.", "years": [2024], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-22-caiso-19-local-band.js"}, {"id": "2026-06-22-caiso-19-outage-regate", "label": "caiso 19 outage regate", "date": "2026-06-22", "shorthand": "caiso-19-outage-regate", "definition": "3-YEAR re-gate of the caiso-15 all-flags keeper (commitment, priced-interchange, 2024 hydro repin + EIA-930 monthly, gas-hub-basis overlay, import gas-coupling + solar-shape) on the net-load-filtered CAMPD unit-outages (commit b0c41cb). Byte-faithful; only the outage input changed. 2024 reproduces caiso-18 (the 2024-only re-gate) EXACTLY (mean 41.17, neg 408 @ 91.9% precision), confirming 3-yr consistency. LMP gating (vs actual DA; 2023 has no actual LMP yet -> fuel-mix-gated only): 2024 mean 41.17 vs actual 35.85 (resid +5.32), neg 408 @ 91.9%/recall 49.7%; 2025 mean 49.31 vs actual 34.62 (resid +14.69), p95 79.81 vs 58.87 (+20.94), neg 16 vs 561 (prec 37.5%, recall 1.1%) -- 2025 runs structurally HOT and misses the negative tail (a known open issue, not introduced here). Model system price avg: 2023 62.17, 2024 41.17, 2025 49.31. Gas TWh vs EIA-923: 2023 66.15/76.04 (-13%), 2024 71.85/67.68 (+6%), 2025 71.32/55.18 (+29%). The CC-over/peaker-under mix defect (TASK-2, a commitment/merit-order property) persists across all 3 years. Companion to the 2024-only caiso-18; see DIAGNOSIS-caiso-fleet-mix-outage-2026-06-21.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-22-caiso-19-outage-regate.js"}, {"id": "2026-06-22-miso1-baseline", "label": "miso1 baseline", "date": "2026-06-22", "shorthand": "miso1-baseline", "definition": "Calibration run from bundle miso1_baseline.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-22-miso1-baseline.js"}, {"id": "2026-06-22-neiso-24-local-band", "label": "neiso 24 local band", "date": "2026-06-22", "shorthand": "neiso-24-local-band", "definition": "neiso 24 local-band outage regate (NEW KEEPER, supersedes neiso 23). The neiso-23 keeper config (scripts/run_calibration_full.py --iso NEISO --year 2023 2024 2025 --commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly; gas-hub-basis monthly overlay on by default; CHP BTM basis fix in code) re-solved BYTE-FAITHFULLY on the LOCAL (seasonal) net-load outage band \u2014 high_load_mask now uses a centered rolling +/-30d window (commit 152bb99) instead of a single annual percentile, recovering genuine multi-week shoulder maintenance outages. ONLY the outage input changed vs neiso 23 (regenerated data/raw/campd-unit-outages-NEISO.csv, auto picked up). NEAR-NO-OP as predicted by the keeper's dispatch headroom (neiso-23 noted the same for the annual-band re-gate): CC_REGULAR 52.32/56.48/57.75 TWh (neiso-23 52.34/56.54/57.89; |d|<=0.14); system gas volume error -1.5%/-1.4%/+0.2% (neiso-23 -1.3/-1.6/+0.4). LMP demand-wtd model mean 33.93/39.23/68.33 (neiso-23 34.06/39.00/69.60; vs actual DA 36.82/41.47/67.86 -> -7.8%/-5.4%/+0.7%, marginally closer to actual on 2024/2025, ~flat 2023). Hourly hub MAE 15.23/14.11/21.60. TAIL PRESERVED: model hrs>$200 0/0/13 (IDENTICAL to neiso-23; actual 72/43/290) \u2014 summer/winter scarcity neither collapsed nor re-inflated (2025 model max $258.98). The local band is the forecast-defensible exogenous outage input (keys on net load, not price) and produces an equivalent-or-marginally-better calibration; adopted as the keeper-of-record on the correct input. Carries forward all neiso-23/neiso-22 caveats (priced-import seam node required before a forecast run; daily-AGT winter-oil convexity stays rejected).", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-22-neiso-24-local-band.js"}, {"id": "2026-06-22-neiso-25-fullstop-override", "label": "neiso 25 fullstop override", "date": "2026-06-22", "shorthand": "neiso-25-fullstop-override", "definition": "neiso 25 fullstop-override outage re-gate (NEW KEEPER, supersedes neiso 24). The neiso-24 keeper config (run_calibration_full.py --iso NEISO --year 2023 2024 2025 --commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly; monthly gas-hub-basis overlay on by default; CHP BTM basis fix in code) re-solved on the SHARED FULL-STOP DURATION OVERRIDE outage input (commits 56ca468/debad10): filter_revealed_outages now keeps a detected down-span if it overlaps >=24 high-net-load hours OR is a sustained full stop (span mean-CF<0.02) for >=14 continuous days, recovering the thin layer of genuinely-mechanical 14-20d weeks-long dead stops the local band still dropped at the 24h overlap margin. Measured-only (CAMPD CF + EIA-930 net load), one shared N=14/depth across all ISOs, no per-ISO constant, no price/MWh-residual (claude.md #11/#12: keep real measured outages). NEISO recovered +39 windows / 15 spans (Merrimack coal, Granite Ridge/Newington/Westbrook/Bellingham CC, Stony Brook, Pittsfield), 0.6% of detected GW-days, all small units; the STEP-1 audit (docs/multi-iso/outage-gate-fullstop-override-2026-06.md) predicted a near-no-op for NEISO and it is. ONLY the outage CSV changed vs neiso 24 (auto picked up). RESULT vs neiso 24: gas tot 54.82/58.92/60.32 TWh vs EIA-930 55.47/59.64/60.09 -> -1.2%/-1.2%/+0.4% (neiso-24 -1.5/-1.4/+0.2, marginally CLOSER to EIA-930 on 2023/24); CC_REGULAR 52.35/56.50/57.88 (neiso-24 52.32/56.48/57.75; |d|<=0.13). LMP model mean 33.96/39.24/68.74 (neiso-24 33.93/39.23/68.33) vs actual DA 36.82/41.51/67.86 -> -7.8%/-5.5%/+1.3%. Hourly hub MAE vs actual RT 15.24/14.10/21.64 (IDENTICAL to neiso-24 15.23/14.11/21.60). TAIL PRESERVED: model hrs>$200 0/0/14 (neiso-24 0/0/13; actual RT 72/43/290), 2025 model max $258.98 unchanged -- the recovered winter full-stops (Granite Ridge/Merrimack Feb 2025) add exactly one marginal 2025 scarcity hour, neither collapsing nor re-inflating the tail. The full-stop override is the structurally-correct forecast-defensible exogenous outage input (keys on net load + measured CF, regenerates forward) and produces an equivalent-or-marginally-better calibration; adopted as keeper-of-record on the correct input. Carries forward all neiso-24/23/22 caveats: priced-import seam node REQUIRED before a forecast run (imports on a fixed EIA-930 schedule); winter oil under-generation (model 0.00/0.00/0.06 vs EIA-930 0.32/0.37/1.24 TWh) is the monthly-AGT-granularity limit and the dominant remaining residual -- the >$200 winter tail (0/0/14 vs 72/43/290) is downstream of it; daily-AGT winter-oil convexity stays REJECTED as a fitted constant (derive from measured daily AGT spot, upload U4).", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-22-neiso-25-fullstop-override.js"}, {"id": "2026-06-22-nyiso-16-transco-daily", "label": "nyiso 16 transco-daily-gas", "date": "2026-06-22", "shorthand": "nyiso-16-transco-daily", "definition": "Mechanism-D fix #1(a): DAILY Transco Z6 NY gas overlay. Keeper config + --gas-hub-basis-overlay --gas-hub-basis-daily, where the overlay's within-month shape is the REAL measured EIA NG Weekly Transco Z6 NY daily spot (scripts/fetch_transco_daily_spot.py -> transco_z6_ny_daily.csv, 674 trading days; daily monthly means reproduce the nyiso-15 monthly file to <$0.06, captured Henry Hub matches EIA RNGWHHD to $0.02). _nyiso_hub_daily_gas_prices scales that shape onto the monthly Iroquois-Z2 level, EXACTLY mean-preserving (annual gas burn/mix unchanged). VALIDATED positive (not a probe): does what the nyiso-15 monthly overlay could not -- Jan-2025 within-month smear fixed (+39.3 -> -1.97), 2025 summer under-price lifted (Jul -10 -> -1.1); monthly-LMP MAE 5.1/5.7/5.1 (keeper 8.0/4.3/6.3, monthly-15 5.6/5.9/7.5) -- best NYISO MAE on 2023 and 2025 and best average; and it RESTORES the 2025 net-interchange band the monthly overlay broke (117.5% OUT -> 109.8% IN, mean-preserving daily shape no longer pushes the annual import level out). Breaks NO volume band the keeper holds: every band where the keeper is in, daily is in (2025 interchange improved); every band where daily is out (2024/25 gas -9.8%/-6.2% vs EIA-930, 2023 interchange 74.2%) the keeper sits on the same EIA-930/923 basis floor by the same margin (keeper 2024 gas re-measured -8.8%). Keeper nyiso 11 STILL STANDS, gated on two non-daily-lever items: (1) the flat-annual Iroquois-Transco spread over-levels summer (Jul/Aug +10) -- fix #1(b), a real monthly Iroquois Z2 (EIA free has none), still data-blocked; (2) Dec-2024 -27.5 is the now-unmasked mechanism-B RCPF scarcity tail (actual RT $67.8), not mechanism D. Supersedes the keeper once #1(b) lands and B fills the winter tail. Zero tuning; every input sourced. See docs/nyiso-backcast-residual-attribution-2026-06.md section 4e.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-22-nyiso-16-transco-daily.js"}, {"id": "2026-06-22-nyiso-17-local-band", "label": "nyiso 17 local band", "date": "2026-06-22", "shorthand": "nyiso-17-local-band", "definition": "nyiso 17 local-band outage regate (local-band re-solve of the nyiso-16 daily-Transco lineage). The nyiso-16 config (nyiso-11 keeper + --gas-hub-basis-overlay --gas-hub-basis-daily: measured EIA Transco Z6 NY daily spot within-month shape, mean-preserving on the monthly Iroquois-Z2 level; commitment + priced interchange + NYISO harness defaults) re-solved BYTE-FAITHFULLY on the LOCAL (seasonal) net-load outage band \u2014 high_load_mask centered rolling +/-30d window (commit 152bb99) instead of the single annual percentile. ONLY the outage input changed (regenerated data/raw/campd-unit-outages-NYISO.csv, auto picked up); the committed CSV is now the forward-correct NYISO outage input. Daily Transco overlay confirmed firing (658 gas gens repriced 12/12 months, winter max $30.19/MMBtu). Canonical gate (model vs actual RT): 2023 annual mean $36.44 vs $30.29 (+6.16; over-prices winter/shoulder \u2014 the documented flat-annual Iroquois-Transco summer over-level / fix #1(b), data-blocked), 2024 $37.57 vs $35.98 (+1.60; Dec -27.18 is the unmasked mechanism-B RCPF winter scarcity tail, not mechanism D), 2025 $61.19 vs $60.73 (+0.46; Jan -3.0, Jul -4.6). Model hrs>$200 1/0/57 (actual 31/27/119) \u2014 summer/winter tail present, not collapsed. NYISO has keeper dispatch headroom (imports/hydro/nuclear), so the outage re-gate is near-equivalent to nyiso-16. NOTE: a byte-clean A/B vs nyiso-16 is basis-limited \u2014 its bundle parquets are gitignored \u2014 so this is reported on absolute gate, not delta. Keeper-of-record nyiso 11 STILL STANDS (the daily-Transco overlay supersedes only once fix #1(b) lands and mechanism-B fills the winter tail, per nyiso-16); this run carries the forward-correct local-band outage input into that lineage.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-22-nyiso-17-local-band.js"}, {"id": "2026-06-22-nyiso-18-local-floors", "label": "nyiso 18 local floors", "date": "2026-06-22", "shorthand": "nyiso-18-local-floors", "definition": "(PROBE) Long Island local self-supply floor (NYISO LMIC, frac 0.45) + HQ/Ontario firm-import baseload. STRUCTURAL fix: LI in-zone generation 3.7->9.3 TWh (real 8.5) \u2014 the -4.8 TWh dispatch error is fixed and the LI dual-fuel units fire. Price MAE 8.2/4.0/10.9 (keeper ~8.0/4.3/6.0): 2024 better, but the floor adds cheap forced supply on top of the already-missing scarcity tail and worsens 2025 (Jun/Jul -22..-31). Per rule #1 the structurally-correct floor stays in code (default OFF); it becomes a keeper once the scarcity tail (fix #3 / in-LP reserve co-optimization for NYC peakers) lands. See docs/nyiso-dispatch-validation-2026-06.md.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-22-nyiso-18-local-floors.js"}, {"id": "2026-06-22-nyiso-19-locational-reserve", "label": "nyiso 19 locational reserve", "date": "2026-06-22", "shorthand": "nyiso-19-locational-reserve", "definition": "(PROBE) Fix #3: in-LP LOCATIONAL reserve co-optimization for NYISO (NYCA-system plus nested East/SENY/NYC RCPF families, FERC ER21-502 / RS4 anchors), on top of the LI self-supply + firm-import floors (--energy-reserve-coopt --nyiso-local-selfsupply --nyiso-firm-imports). Holding the import-constrained downstate pocket to its locational reserve recovers the summer scarcity tail the NYCA-aggregate curve and the post-solve RCPF adder cannot dispatch: reserve fires only in genuine summer scarcity (Jul/Aug/Sep), 2025 summer under-bias eased (Jun -30.7->-14.6, Jul -22.1->-15.8 vs the LI-floor probe), 2025 price_shape now PASSES (NRMSE 0.16) and 2024 price fully PASSES, dispatch r 0.81-0.87 all years. NOT a keeper: the aggregate is gated by a PRE-EXISTING winter/January downstate over-pricing (2023 price_mean +13%, shape 0.402) that a BASE-vs-COOPT A/B proved is identical with the co-opt off (a gas/dual-fuel marginal-unit residual, the next root cause) -- so it does not beat keeper nyiso-11. Per rule #1 the mechanism stays (default OFF).", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-22-nyiso-19-locational-reserve.js"}, {"id": "2026-06-22-ordc-pub2-published-ordc", "label": "ordc-pub2 \u2014 published-ORDC curve re-baselined on local-30 outages", "date": "2026-06-22", "shorthand": "ordc-pub2-published-ordc", "definition": "PROBE. run143_redo (current local-30 outages) with ONE change: the co-opt ORDC reserve-demand curve uses ERCOT's PUBLISHED NP6-576-ER seasonal mu/sigma (KEEPER_ORDC_TABLE=ercot_ordc_lolp_params.csv) instead of the neutral mu=0 fallback. Grounded input, NOT a fit. Demand-wtd avg / h>200 / h>500 vs actual: 2023 42.9/135/78 (run143_redo 35.2/89/51; actual 48.4/181/104); 2024 28.0/44/31 (23_redo 25.4/33/23; actual 26.8/53/16); 2025 32.6/3/1 (32.5/1/0; actual 32.5/31/3). VOLUME RE-GATE: C1 fuel-mix + C2 FAILs are BYTE-IDENTICAL to run143_redo (2024 CC_REGULAR +10.0%, ST_GAS -6.72 TWh, CT_PEAKER -3.17, coal -2.7%) -> the curve is PRICE-ONLY (DAM-BASE~0), no new volume regressions; the operating-shape/ST_GAS/CT_PEAKER FAILs pre-exist in run143. KEEPER-READINESS: ready on VOLUMES, NOT yet on PRICE SHAPE -- it lifts 2023 toward actual (closing most of the undershoot) but OVER-fires the 2024 deep tail (h>500 31 vs actual 16) and the P90-P99 'moderately scarce' band stays HOLLOW (2024 P95 29.6 vs 61.4). Adopt only PAIRED with the reserve-SUPPLY lever (re-scope ercot_reserve_eligible to online RTOLCAP; the measured RTOLCAP/RTORPA series is now committed under data/raw/ercot/). NOT-YET (probe, unattested).", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-ordc-pub2-published-ordc.js"}, {"id": "2026-06-22-pjm-39-local-band", "label": "pjm 39 local band", "date": "2026-06-22", "shorthand": "pjm-39-local-band", "definition": "pjm 39 local-band outage regate (NEW KEEPER, supersedes pjm 38). The pjm-38 keeper config (retiree_cems_cap=True) re-solved BYTE-FAITHFULLY on the LOCAL (seasonal) net-load outage band \u2014 scripts/derive_campd_outages.py high_load_mask now measures the high-load percentile over a centered rolling +/-30d window (commit 152bb99) instead of a single annual percentile, recovering genuine multi-week shoulder CCGT maintenance outages the annual band wrongly dropped while still dropping short economic-idle gaps. ONLY the outage input changed vs pjm 38 (both regenerated data/raw/campd-outages-PJM.csv facility + campd-unit-outages-PJM.csv unit, auto picked up); no offers/curves/flags retuned. Direction as predicted: recovering shoulder outages puts MORE coal/CC offline in shoulder months -> firmer prices and LESS of the annual-band coal over-run/over-export. STRICT IMPROVEMENT over pjm 38 on every axis. LMP demand-wtd mean (model vs actual RT) 28.29/26.12/35.01 (pjm38 28.12/26.17/34.63; actual 28.44/29.53/42.89); hourly hub MAE 7.94/9.75/13.37 (pjm38 8.12/10.49/15.82 \u2014 better all 3 yrs); coal-tot resid +11.4/+3.0/+11.1% (pjm38 +17.3/+13.9/+22.8); net-export resid +31/+17.5/+93% (pjm38 +69/+65/+204); in-tolerance fails 11->7. Model hrs>$200 0/0/0 unchanged (actual 6/18/59) \u2014 the model still does not fire PJM's scarcity tail, a documented SEPARATE issue, neither collapsed nor re-inflated here. Summer not under-fired (2023 Jul/Aug model 29.1 vs actual 31.8). Remaining coal over-run + over-export is PJM's documented forecast-native coal-cost/offer issue (docs/multi-iso/pjm-coal-mustrun-floor.md), made LESS visible than the annual band rather than newly introduced \u2014 the next frontier, not chased in the outage step. [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-22-pjm-39-local-band.js"}, {"id": "2026-06-22-pjm-40-coal-fidelity", "label": "pjm 40 coal fidelity", "date": "2026-06-22", "shorthand": "pjm-40-coal-fidelity", "definition": "pjm_40_coalfidelity: pjm_39 local-band config (verbatim) + the heat-input->MWh proxy for grossLoad-blank coal + the coal-cogen CHP/BTM holdout (Eastman/St Nicholas/John B Rich/...). Measured-anchored, no new flags; 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-22-pjm-40-coal-fidelity.js"}, {"id": "2026-06-22-pjm-41-fullstop-override", "label": "pjm 41 fullstop override", "date": "2026-06-22", "shorthand": "pjm-41-fullstop-override", "definition": "pjm_40_coalfidelity: pjm_39 local-band config (verbatim) + the heat-input->MWh proxy for grossLoad-blank coal + the coal-cogen CHP/BTM holdout (Eastman/St Nicholas/John B Rich/...). Measured-anchored, no new flags; 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-22-pjm-41-fullstop-override.js"}, {"id": "2026-06-22-pjm-42-campd-nan", "label": "pjm 42 campd nan", "date": "2026-06-22", "shorthand": "pjm-42-campd-nan", "definition": "pjm_37_retiree: pjm_36 refconvex config + within-window retiree CEMS measured-availability cap (retiree_cems_cap=True) \u2014 each retiree plant limited to its measured monthly CAMPD envelope, closing the Homer City phantom-baseload over without tuning to the coal target, 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-22-pjm-42-campd-nan.js"}, {"id": "2026-06-22-published-ordc-curve-np6", "label": "ercot published-ORDC curve (NP6-576-ER, grounded)", "date": "2026-06-22", "shorthand": "published-ordc-curve-np6", "definition": "PROBE. run143 keeper recipe with ONE change: the energy+reserve co-opt ORDC reserve demand curve uses ERCOT's PUBLISHED NP6-576-ER seasonal mu/sigma (ercot_ordc_lolp_params.csv, mu~924/sigma~1348) instead of the ungrounded neutral mu=0/sigma=1400 fallback. Grounded input (ERCOT's published rule), NOT fitted to the LMP. Motivation: run143's monthly shape is bimodal and the price duration curve is hollow in the P90-P99 'moderately scarce' band; the keeper curve only priced reserve ~920 MW too low. Scores (demand-wtd avg / h>200 / h>500, vs actual): 2023 45.3/156/94 (run143 36.5/104/56; actual 48.4/181/104); 2024 25.2/34/21 (run143 23.2/22/16; actual 26.8/53/16); 2025 31.5/4/1 (run143 31.4/1/0; actual 32.5/31/3). FINDING: a single grounded curve moves all 3 years' average AND scarcity-hour frequency toward actual without over-inflating 2025 or exploding (unlike the ECRS-requirement and unit-commitment probes, which both over-fired). RESIDUAL: the duration curve P90-P99 band is still under-priced (2024 model P95 27.9 vs actual 61.4), pointing the next GROUNDED structural lever at the reserve-SUPPLY definition (online/RTOLCAP vs all dispatchable headroom), not the curve. Volume re-gate pending before keeper (operating-shape gate flagged 19 regressions).", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-published-ordc-curve-np6.js"}, {"id": "2026-06-22-run143-redo-rebaseline-local30", "label": "run143 redo \u2014 re-baseline on local-30 outages", "date": "2026-06-22", "shorthand": "run143-redo-rebaseline-local30", "definition": "PROBE / fresh baseline. The run143 KEEPER recipe re-solved BYTE-FAITHFULLY, changing ONLY the outage inputs: the ERCOT CAMPD outage filter switched from the over-tight single-annual net-load band to the centered +/-30d LOCAL net-load band (CC outage GW-days 2906->5997). The committed run143 numbers were solved on the stale annual-band outages, so this re-baseline is the correct comparison point for any reserve-curve lever. Scores (demand-wtd avg / hourly-MAE / h>200 / h>500, vs actual RTSPP): 2023 35.2/27.9/89/51 (stale run143 36.5/-/104/56; actual 48.4/181/104); 2024 25.4/15.0/33/23 (stale 23.2/22/16; actual 26.8/53/16); 2025 32.5/11.6/1/0 (stale 31.4/1/0; actual 32.5/31/3). The local-30 outages nudge 2024's deep tail to a mild OVER-fire (h>500 23 vs actual 16) and leave the P90-P99 'moderately scarce' band still HOLLOW (2024 model P95 29.6 vs actual 61.4; 2025 P95 49.7 vs 76.7) \u2014 the documented monthly-shape residual the reserve-demand-curve / reserve-supply levers target. Operating-shape gate: 10 regressions vs the (old-outage) keeper baseline, dominated by ST_GAS (cf_emd/r) and CC_REGULAR \u2014 these are the outage-change shape shifts, the pre-existing baseline for the published-ORDC re-gate. NOT a keeper (no attestation; pending volume re-gate).", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run143-redo-rebaseline-local30.js"}, {"id": "2026-06-22-run144-local-band-outages", "label": "run144 local band outages", "date": "2026-06-22", "shorthand": "run144-local-band-outages", "definition": "KEEPER (supersedes run143). Byte-faithful re-solve of the run143 keeper recipe (scripts/probes/_keeper_2023as_run.py: measured-2023 storage-AS commitment + load-RRS-UFR credit, ST_GAS committed delta restored to 0.0, storage-AS-from-year 2025, ECRS off) with the ONLY changed input being the regenerated ERCOT outage CSVs, now on the LOCAL (seasonal) net-load band (high_load_mask = centered rolling +/-30-day net-load percentile vs the prior single-annual percentile; commit 152bb99). The local band restores real shoulder CCGT maintenance the over-tight annual band wrongly dropped as economic idle (ERCOT CC outage GW-days 2906 -> 5997, still -36% vs unfiltered; short economic-idle still dropped; summer preserved). RESULT vs run143 (annual band; act in parens): 2023 avg 36.5->35.2 / MAE 12.0->14.0 / tail h>200 104->89, h>500 56->51 (48.4, 181/104); 2024 23.2->25.4 / 9.6->7.1 / 22->33, 16->23 (26.8, 53/16); 2025 31.4->32.5 / 2.9->2.0 / 1->1, 0->0 (32.5, 31/3). Mean monthly MAE 8.2 -> 7.7. Expected direction confirmed: more shoulder CC offline -> CC_REGULAR grid -2.6 TWh (2024), displaced to ST_GAS (+2.0) and CT_PEAKER (+0.8) toward bench; modestly firmer 2024/2025 shoulder prices (cooler than the pre-fix VOLL over-fire: Oct-2024 model $22 vs act $24, no shoulder over-fire); summer roughly preserved (one flag: 2024 summer h>500 16->23, a modest firming in real scarcity months, not the shoulder economic-idle re-inflation). No class regresses; all in-scope fails move TOWARD bench; fuel split passes all 3 years (2023 gas -1.5/coal +0.3; 2024 +1.3/-0.6; 2025 +0.6/+0.1 vs EIA-930). DETERMINATION: NOT-YET (C6 governance attested PASS; metric caveat budget exceeded 2 hard / 1 \u2014 the documented structural ERCOT misses: CT non-CEMS peakers, CC nodal-congestion residual, ST_GAS committed/AS-held wedge, cheap-gas 2024 coal, 2023 ~42% out-of-market). Same lineage status as run143; the rubric is built to fail a keeper carrying these documented limitations. Gated CLEAN vs the prior keeper, adopted on the more physically-correct (local-band) outage input.", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run144-local-band-outages.js"}, {"id": "2026-06-22-run145-rtordpa-overlay", "label": "run145 rtordpa overlay", "date": "2026-06-22", "shorthand": "run145-rtordpa-overlay", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run145-rtordpa-overlay.js"}, {"id": "2026-06-22-run146-zonal-gas-basis", "label": "run146 zonal gas basis", "date": "2026-06-22", "shorthand": "run146-zonal-gas-basis", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run146-zonal-gas-basis.js"}, {"id": "2026-06-22-run147-new-outage-baseline", "label": "run147 new outage baseline", "date": "2026-06-22", "shorthand": "run147-new-outage-baseline", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run147-new-outage-baseline.js"}, {"id": "2026-06-22-run147-zonal-gas-ep", "label": "run147 zonal gas ep", "date": "2026-06-22", "shorthand": "run147-zonal-gas-ep", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run147-zonal-gas-ep.js"}, {"id": "2026-06-22-run149-zonal-gas-prb", "label": "run149 zonal gas prb", "date": "2026-06-22", "shorthand": "run149-zonal-gas-prb", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run149-zonal-gas-prb.js"}, {"id": "2026-06-22-run150-stgas-netload-drag", "label": "run150 stgas netload drag", "date": "2026-06-22", "shorthand": "run150-stgas-netload-drag", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-22-run150-stgas-netload-drag.js"}, {"id": "2026-06-23-caiso-20-bidir-intertie", "label": "caiso 20 bidir intertie", "date": "2026-06-23", "shorthand": "caiso-20-bidir-intertie", "definition": "Calibration run from bundle caiso_bidir_intertie.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-20-bidir-intertie.js"}, {"id": "2026-06-23-caiso-21-bidir-floor", "label": "caiso 21 bidir floor", "date": "2026-06-23", "shorthand": "caiso-21-bidir-floor", "definition": "(PROBE \u2014 rejected, keeper stays caiso-import-cap-floor) Attempt to UNIFY the two 2026-06-23 CAISO threads: the bidir-intertie diurnal-shape fix (single signed WECC flow, both legs at the measured hub) PLUS the keeper's level levers ported onto it \u2014 the per-tranche delivered-cost basis now applied to the bidir import legs (line-loss on the positive hub + OATT wheeling, guarded so a negative hub can't break arbitrage-freeness) and the RA gas-commitment floor 0.80 \u2014 with interchange shaping + negative renewable offers. REGRESSES the keeper on every axis: 2024 neg-price hours 194 (keeper 815, actual ~800), net interchange -17.68 TWh (keeper -30.4, actual -32.4), p10 LMP $33.63 (keeper $1.40), mean $48.8 (keeper ~42, actual 35.8); diurnal corr +0.95 (2023) but only +0.09 (2024) and -0.12 (2025), i.e. the gas floor drags the bidir diurnal win back toward zero. ROOT CAUSE: the gas floor (forces gas online) and the delivery basis (raises import cost) BOTH suppress imports, so on the single-flow bidir node the model badly under-imports and the bidir export leg sells the midday surplus at the POSITIVE hub instead of crashing to negative \u2014 the negative tail the keeper relies on disappears, and the level levers prove ANTAGONISTIC with the bidir representation, not additive. Next: decompose (bidir+floor only / bidir+basis only) to find which lever is bidir-compatible; see results/calibration/NEXT-caiso-roadmap-2026-06-23.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-21-bidir-floor.js"}, {"id": "2026-06-23-caiso-22-bidir-floor", "label": "caiso 22 bidir+floor-only", "date": "2026-06-23", "shorthand": "caiso-22-bidir-floor", "definition": "(PROBE \u2014 rejected, keeper stays caiso-import-cap-floor) Decomposition of the rejected caiso-21 unify: the single signed WECC bidir intertie (both legs at the measured hub) PLUS the RA gas-commitment floor 0.80, with NO per-tranche delivered-cost basis on the import legs (basis reverted in transmission.py inject_caiso_bidir_intertie_prices; the basis is the separate basis-only probe). Isolates whether the FLOOR alone is bidir-compatible. Run: --caiso-bidir-intertie --interchange-shaping --negative-renewable-offers --gas-hub-basis-overlay --priced-interchange --hydro-eia930-monthly --caiso-gas-commitment-floor, 3-yr. RESULT 2024: neg-price hrs 221 (keeper 815, actual ~800), net interchange -22.36 TWh (keeper -30.4, actual -32.4), p10 LMP $32.24 (keeper $1.40), mean $46.81 (keeper ~42, actual 35.8), diurnal corr +0.22. 2023: net -19.41 (actual -28.87), neg 48, mean 77.71, corr +0.95. 2025: net -30.63 (actual -36.16), neg 9, mean 52.01, corr +0.11. VERDICT: does NOT beat the keeper. Dropping the basis recovered some imports/tail vs the unify (2024 net -22.36 vs -17.68, neg 221 vs 194, corr +0.22 vs +0.09) \u2014 so the delivery basis WAS part of the import suppression \u2014 but the model STILL badly under-imports and the negative tail STILL collapses (221 vs keeper 815/actual ~800) and the body stays high. The bidir diurnal corr DOES survive the floor (positive every year: +0.95/+0.22/+0.11, vs the unify's +0.95/+0.09/-0.12), so the floor is diurnal-COMPATIBLE but level-ANTAGONISTIC: the RA gas floor forces gas online and suppresses imports / the negative tail on the single-flow node even with no basis. CONCLUSION: the FLOOR is (also) an import-suppressor on the bidir node \u2014 neither lever fully composes with bidir; basis was a secondary suppressor (confirm via the basis-only probe). Keeper unchanged. See results/calibration/NEXT-caiso-roadmap-2026-06-23.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-22-bidir-floor.js"}, {"id": "2026-06-23-caiso-23-bidir-basis", "label": "caiso 23 bidir+basis-only", "date": "2026-06-23", "shorthand": "caiso-23-bidir-basis", "definition": "(PROBE \u2014 rejected, keeper stays caiso-import-cap-floor) DECOMPOSITION of the rejected caiso-21 unify: isolate the per-tranche delivered-cost BASIS on the bidir-intertie import legs ALONE, with the RA gas-commitment floor explicitly OFF (--no-caiso-gas-commitment-floor; note the flag DEFAULTS ON for CAISO, so omitting it does NOT disable the floor). bidir-intertie + interchange shaping + negative renewable offers + gas-hub-basis overlay, 3-yr. RESULT: basis-only is nearly byte-identical to caiso-21 (basis+floor) on every 2024 axis \u2014 neg-price hours 194 (caiso-21 194; keeper 815; actual ~800), net interchange -19.09 TWh (caiso-21 -17.68; keeper -30.4; actual -32.38), p10 LMP $33.63 (caiso-21 $33.63; keeper $1.40), mean $48.79 (caiso-21 48.8; keeper ~42; actual 35.8), import hours 81.8% vs actual 89.0%; diurnal corr -0.04 (2024), -0.12 (2025), +0.94 (2023 \u2014 static-ladder placeholder, no measured hub so the basis is INACTIVE that year, not informative). 2025 net interchange -25.70 TWh (keeper -38.6; actual -36.16). CONCLUSION: removing the floor barely moved anything, so the DELIVERY BASIS \u2014 not the gas floor \u2014 is the import suppressor on the single-flow bidir node. The multiplicative line-loss markup is too aggressive on the already-capped (8.3 GW) bidir leg: it over-prices imports, collapses the negative tail and net-import magnitude, and drags the diurnal correlation the standalone bidir keeper (caiso-20) flipped POSITIVE back to negative. Next: try wheel-only (additive) delivery or a smaller loss factor on the bidir import legs, grounded as a physical input (rule #12), NOT tuned to the residual; otherwise the diurnal-shape fix (bidir) and the merit-order-restoring basis are mutually exclusive on the capped single-flow node and the keeper stays. See results/calibration/NEXT-caiso-roadmap-2026-06-23.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-23-bidir-basis.js"}, {"id": "2026-06-23-caiso-24-bidir-wheel", "label": "caiso 24 bidir+wheel-only (PROBE)", "date": "2026-06-23", "shorthand": "caiso-24-bidir-wheel", "definition": "PROBE (failed keeper gate). Bidir WECC intertie + RA gas floor 0.80 + ADDITIVE wheel-only delivery basis on the import legs (the per-tranche OATT PTP wheeling charge of CAISO_IMPORT_DELIVERY_BASIS, WITHOUT its multiplicative loss\u00b7max(hub,0) markup). Decompose follow-up to caiso-22 floor-only / caiso-23 basis-only: tests whether the minimal additive wheel restores the rising delivered-import merit order without over-suppressing imports. It does not \u2014 wheel-only lands essentially on basis-only (2024 net -18.66 vs -19.09, neg 194=194, mean 48.34 vs 48.79) and worse than floor-only on both level (net -22.36, neg 221, mean 46.81) and shape (2024 corr +0.14 < floor-only +0.22; 2025 corr -0.07, not positive every year). Confirms the bidir diurnal-shape fix and any merit-order-restoring delivery basis are mutually exclusive by design on the capped 8.3 GW single-flow node; keeper stays until measured WECC hub diurnal prices land (roadmap option B).", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-24-bidir-wheel.js"}, {"id": "2026-06-23-caiso-25-corridor-deliverability", "label": "caiso 25 corridor-deliverability", "date": "2026-06-23", "shorthand": "caiso-25-corridor-deliverability", "definition": "NEW KEEPER. Adds the measured WECC corridor deliverability limit (--caiso-corridor-flow-limit) on top of the per-hub signed legs: each import corridor's import-direction link flow is capped at the per-(month x hour-of-day) p95 measured net import (an ATC proxy from EIA-930 BA-to-BA interchange; one-sided, export keeps the physical TTC). Fixes the diurnal phase residual -- net-import corr flips POSITIVE both scored years (2024 -0.15->+0.08, 2025 -0.36->+0.03), the first per-hub run with the right diurnal sign -- and fixes 2025 over-import (net -41.1->-36.3 TWh vs actual -36.2). Removing the phantom midday thermal import lifts the body to its honest level (mean 2024 +2.6/2025 +4.9) and drops neg-hours (459->346/193->61): the exposed in-state midday over-pricing residual (next phase), NOT a reason to revert (rule #1). 2024 net now under-imports (-28.3) -- the exposed evening import shortfall. P0->P1, commitment off; 2023 = static-ladder hub fallback but corridor cap active (corr +0.97).", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-25-corridor-deliverability.js"}, {"id": "2026-06-23-caiso-import-cap-floor", "label": "caiso import cap floor", "date": "2026-06-23", "shorthand": "caiso-import-cap-floor", "definition": "CAISO keeper: this session's aggregate WECC simultaneous-import cap (8.3 GW) + per-tranche delivered-cost basis over the measured hub MCE, run with the validated RA gas-commitment floor (0.80) and negative renewable offers ON. The floor mechanisms make the model long midday so the price floor crashes to reality: 2024 negative-price hours 815 (~800 actual), LMP p10 $1.40 / min -$20, net interchange -30.4 TWh vs -32.4 actual; 2025 net -38.6 vs -36.2. 2023 over-imports (net -40 vs -29, 99% import hours) because it has no measured WECC hub series (OASIS Jan-Feb aged out) and falls back to the static import ladder. Residual: mean LMP still ~$8 high (evening ramp \u2014 missing AS/reserve co-optimization) and diurnal phase corr negative (separate bidirectional-zone work).", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-import-cap-floor.js"}, {"id": "2026-06-23-caiso-import-simul-cap", "label": "caiso import simul cap", "date": "2026-06-23", "shorthand": "caiso-import-simul-cap", "definition": "(PROBE) Import-isolation diagnostic: aggregate WECC import cap + delivered-cost basis, but with the RA gas-commitment floor and negative renewable offers DISABLED (--no-caiso-gas-commitment-floor --no-negative-renewable-offers) to isolate the import-level effect. Fixes the import quantity (tail -8.3 GW, body median -4.3 GW) but leaves the midday price floor high (only 117 negative hours, LMP min -$5). The keeper that re-enables the floor mechanisms is 2026-06-23-caiso-import-cap-floor.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-import-simul-cap.js"}, {"id": "2026-06-23-caiso-per-hub-intertie", "label": "caiso per hub intertie", "date": "2026-06-23", "shorthand": "caiso-per-hub-intertie", "definition": "CAISO keeper (structurally-faithful successor to caiso-import-cap-floor): byte-identical config, the ONLY change is the measured WECC intertie parquet now carries the FULL delivered nodal LMP (energy+congestion+loss = MCE+MCC+MCL, GHG excluded) per scheduling point instead of the byte-identical system MCE \u2014 so MALIN (PNW/Mid-C) and PALOVRDE (desert-SW) finally differ (2024 MALIN mean 40.1/313 neg-hrs vs PALOVRDE 33.3/949 neg-hrs). The import injector drops the modeled multiplicative line-loss markup (the measured MCL now carries the real loss) and keeps only the OATT wheel (rules #11/#12). Effect: 2024 mean LMP 42->39.24 toward actual 35.8 (the DIAGNOSIS-caiso-body-overprice midday-floor target improves); 2024 neg-hours 815->873 (actual ~800); 2024 net interchange -30.4->-35.95 TWh (actual -32.4) and 2025 -38.6->-44.18 (actual -36.2) \u2014 over-import GREW because the now-cheaper desert-SW PALOVRDE hub pulls more midday import volume; diurnal phase corr still negative (2024 -0.34). 2023 falls back to the static ladder (OASIS Jan-Feb aged out -> incomplete 8760, unchanged from keeper). Residual / next root cause: the over-import is a discovered downstream issue (import cap / DSW gas coupling), NOT a reason to revert the faithful measured input.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-per-hub-intertie.js"}, {"id": "2026-06-23-caiso-per-hub-legs", "label": "caiso per-hub legs + solar-shape (PROBE)", "date": "2026-06-23", "shorthand": "caiso-per-hub-legs", "definition": "PROBE \u2014 per-hub signed legs (--caiso-per-hub-intertie) WITH --caiso-import-solar-shape still ON, to test whether the solar-shape proxy still adds anything once the measured per-hub Palo Verde hub is doing the work. Verdict: REDUNDANT. Nearly byte-identical to the per-hub-signed keeper on every axis (2024 mean 43.49 vs 43.82, neg 535 vs 459, net \u221232.65 vs \u221232.39, corr \u22120.17 vs \u22120.15; 2025 mean 44.55 vs 44.86, net \u221241.48 vs \u221241.11, corr \u22120.38 vs \u22120.36). solar-shape was a no-OASIS proxy that collapsed the desert-SW import offer toward \u2212$20 to manufacture the negative midday tail; the measured per-hub hub now prints that tail directly, and on a signed node the \u2212$20 import offer mildly re-inflates the very midday over-import the per-hub legs fix (slightly worse corr, +76 neg-hrs). Confirms dropping solar-shape from the keeper (rule #11: prefer the measured input over the proxy). Not a keeper.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-per-hub-legs.js"}, {"id": "2026-06-23-caiso-per-hub-signed", "label": "caiso per-hub signed legs", "date": "2026-06-23", "shorthand": "caiso-per-hub-signed", "definition": "CAISO KEEPER candidate \u2014 the structural fix for the over-import (priority 1) the per-hub-intertie keeper surfaced. Splits the single pooled WECC_import node into the two REAL signed corridors \u2014 COI/Path-66 at the Malin hub (WECC_PNW \u2192 NP15) and Path-46/WOR at the Palo Verde hub (WECC_DSW \u2192 SP15) \u2014 each a single net direction per hour priced at its OWN measured intertie hub (--caiso-per-hub-intertie). This unifies the bidir node's per-hub netting (each corridor carries one signed flow, so the cheap Palo Verde midday block reverses to EXPORT instead of flooding the 8.3 GW budget) with the hub-price node's per-hub basis (Malin != Palo Verde), which were thought mutually exclusive. The 8.3 GW simultaneous-import cap is preserved as the WECC_import_simultaneous interface limit re-homed onto the two corridor links. solar-shape DROPPED (the measured per-hub Palo Verde hub already prints the negative midday tail it proxied; redundant on a signed node \u2014 confirmed by the per-hub-legs+solar-shape probe). RESULT vs keeper (2024/2025): net interchange \u221236.04/\u221244.17 \u2192 \u221232.39/\u221241.11 TWh (actual \u221232.38/\u221236.16) \u2014 2024 DEAD-ON, over-import SOLVED; diurnal interchange corr \u22120.35/\u22120.60 \u2192 \u22120.15/\u22120.36 (improved, still negative \u2014 the model still imports midday because the cheap hub invites it; a midday-deliverability mechanism is the remaining priority-2 lever). Mean LMP 39.24/43.03 \u2192 43.82/44.86 and neg-hrs 873/407 \u2192 459/193 REGRESSED \u2014 rule #1: this reveals the keeper's better body was partly an OVER-IMPORT ARTIFACT (cheap midday imports suppressed prices / manufactured negatives); the honest body is higher and the residual is now in-state midday over-pricing (DIAGNOSIS-caiso-body-overprice), NOT import, to fix at root cause. 2023 falls back to the static ladder (OASIS gap). Diagnosis: DIAGNOSIS-caiso-perhub-overimport-diurnal-2026-06-23.md.", "years": [2023, 2024, 2025], "iso": "CAISO", "file": "frontend/data/backcast/runs/2026-06-23-caiso-per-hub-signed.js"}, {"id": "2026-06-23-miso2-importnode", "label": "miso2 importnode", "date": "2026-06-23", "shorthand": "miso2-importnode", "definition": "(PROBE) Adds the forecast-grade reference-price interchange node for MISO (Module M4): PJM/SPP/SERC-South seams, each priced from the neighbor's own gas x heat-rate x EIA-930 load shape (HR 12.3/10.0/12.0; cited interface limits 7.3/4.0/3.0 GW), the LP clearing volume on the spread vs MISO's own LMP. Default-on for MISO via REFERENCE_PRICE_DEFAULT_ISOS; PJM opt-in, ERCOT byte-identical. Also corrected HENRY_HUB_TRAJECTORIES[2025] 2.88->3.52 (actual). Determination NOT-YET: the node is structurally correct and measured-anchored, but MISO's modeled LMP is too low (-6/-14/-13%, pre-existing offer-curve level miss), so fed correctly-priced neighbors the seam EXPORTS MISO's over-cheap energy rather than importing -- net interchange does not reach EIA-930 (model NI +0.1/-7.5/+45.0 vs actual -37.9/-23.1/-19.0 TWh; 2024 imports modestly, 2025 over-exports). Root cause for next pass: MISO price level + the absent firm-hydro (Manitoba) import that a gas-margin seam cannot represent. Mechanism stays in (CLAUDE.md #1); seam not tuned to the net-MWh target (#12).", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso2-importnode.js"}, {"id": "2026-06-23-miso3-reservecoopt", "label": "miso3 reservecoopt", "date": "2026-06-23", "shorthand": "miso3-reservecoopt", "definition": "(PROBE) Adds the in-LP market-wide energy+operating-reserve co-optimization for MISO (scarcity.miso_reserve_coopt_inputs, the MISO analogue of the ERCOT/PJM/NYISO co-opt): requirement = fleet-derived MSSC + 400 MW regulation (~3 GW), VOLL-anchored Reliability-Based Demand Curve to $3,500/MWh, linearised to zero reserve; single footprint-wide reserve family; import node default-on. Determination NOT-YET: the mechanism is structurally correct, live, and sourced (nothing fitted), but FULLY INERT -- reserve_price is exactly $0 in all 26,280 hours, so the energy solution is identical to miso2 (C3a still -9/-17/-14%, net interchange +0.1/-7.5/+45.0 unchanged). The ~3 GW requirement never binds because the perfect-foresight LP holds tens of GW of idle thermal headroom -- the same result the PJM reserve campaign documented. Per CLAUDE.md #1/#11 the requirement was NOT inflated to manufacture scarcity; the structure stays in as the correct baseline. The level miss is carried by market-specific MISO coal offer curves + a firm-hydro (Manitoba) import block (handed off).", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso3-reservecoopt.js"}, {"id": "2026-06-23-miso4-coal-takeorpay", "label": "miso4 coal takeorpay", "date": "2026-06-23", "shorthand": "miso4-coal-takeorpay", "definition": "(NOT-YET; structurally-correct input, fit-neutral) Replaces MISO's uniform ASSUMED coal take-or-pay with the MEASURED EIA-923 Schedule-5 contracted share per plant (coal_takeorpay_MISO.csv) via coal_takeorpay_from_data, wired into split_coal_tranches (MISO is split-fleet, NOT in CAMPD_BINNING_ISOS, so the task's offer_curve_by_group lever is architecturally inert for MISO \u2014 its coal supply curve is t1/t2/t3 from coal_tranche_*_fuel_passthrough). The sunk first tranche now passes 1-contract_share instead of 100%-sunk, mirroring the binned path's campd_tranche_fuel_frac must-run rule. REFUTES the task premise: measured data shows MISO coal is ~97% contract (tonnage-wtd) \u2014 MORE take-or-pay than ERCOT (~71%), not market-bought \u2014 so the deep sunk tranche is correct and coal offers are NOT the C3a/seam lever. Result is near-baseline (coal 180.9/165.5/231.1 vs miso3 181.2/166.1/231.4; meanLMP 29.25/26.15/37.54 vs 29.15/26.12/37.54 still ~9/15/12% low; net interchange +1.4/-6.6/+46.2 vs miso3 +0.1/-7.5/+45.0, marginally MORE export \u2014 vs actual -37.9/-23.1/-19.0). Only the 2 spot-heavy plants (1167 S:100%, 6213 S:47%) bid their first tranche fuller and back down; the 97% contract majority is unchanged. Per CLAUDE.md #1/#12 the measured input stays in even though it doesn't move the residual; the level/import-seam belongs to the firm-hydro (Manitoba) import block (#810) + seam, not the coal curve. ERCOT and the CAMPD-binned ISOs untouched (flag off, byte-identical). energy-reserve-coopt on (inert), import node default-on.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso4-coal-takeorpay.js"}, {"id": "2026-06-23-miso5-firmhydro", "label": "miso5 firmhydro", "date": "2026-06-23", "shorthand": "miso5-firmhydro", "definition": "(KEEPER structure / NOT-YET metrics) Adds a SEPARATE firm-hydro IMPORT block for Manitoba Hydro (~12.3 TWh/yr = 1,400 MW must-flow firm contracted hydro into MISO-North) \u2014 MISO's single largest real import and the structural reason it is a net importer. Firm hydro has no gas x heat-rate analogue, so it is OUTSIDE the gas-margin reference-price seam (PJM/SPP/SERC): a low near-constant offer ($8/MWh, MISO_MANITOBA_FIRM_IMPORT_*) landed directly in MISO-North and floored as must-flow (inject_miso_firm_imports), modeled on the NYISO firm-imports mechanism. Volume from the Manitoba export-contract band, NOT fitted to the residual (#12). Default-ON for MISO (MISO_FIRM_IMPORT_DEFAULT_ISOS); requires --priced-interchange; ERCOT byte-identical. RESULT: net interchange moves toward EIA-930 actual in all 3 yrs (base +0.1/-7.5/+45.0 -> -4.83/-13.31/+39.13 TWh; actual -37.9/-23.1/-19.0) and mean LMP edges DOWN (28.71/25.49/36.78 -> 28.54/25.27/36.40; actual 31.79/30.80/42.85) \u2014 both exactly as predicted (cheap firm hydro raises imports while displacing marginal gas). Gap only HALF closes: the +12.3 TWh import is partly re-exported by the seam because MISO's LMP sits ~6/14/13% low (the pre-existing miso2 root cause), so a correctly-priced seam stays export-biased. Per #1 the correct structure stays in; closing C2/C3a needs the MISO price-LEVEL fix, not a deeper Manitoba block.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso5-firmhydro.js"}, {"id": "2026-06-23-miso6-coalclass", "label": "miso6 coalclass", "date": "2026-06-23", "shorthand": "miso6-coalclass", "definition": "Calibration run from bundle miso6_coalclass.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso6-coalclass.js"}, {"id": "2026-06-23-miso7-zonalload", "label": "miso7 zonalload", "date": "2026-06-23", "shorthand": "miso7-zonalload", "definition": "(PROBE) miso3 reserve-coopt config re-solved on current main with all merged MISO structural work \u2014 per-zone hourly load shapes from EIA-930 sub-BA demand (zones = whole sub-BA/LRZ unions, shares 0.285/0.444/0.271, WI->Central/MO->North), RDT asymmetric links (3000 N->S / 2500 S->N), per-zone wind CF shapes, #812 coal take-or-pay, firm-hydro import. Load-weighted LMP 28.98/25.89/37.11 vs actual 31.79/30.80/42.85 (-8.8/-15.9/-13.4%) \u2014 a few tenths closer than static-share miso3 but the gap persists. Scarcity tail still absent (0h >$200 vs 30/37/88) and zones don't separate (N=C, N<->C link still the 12 GW placeholder). Next levers: a binding N<->C corridor limit and a live scarcity tail, not load-share tuning.", "years": [2023, 2024, 2025], "iso": "MISO", "file": "frontend/data/backcast/runs/2026-06-23-miso7-zonalload.js"}, {"id": "2026-06-23-neiso-26-ps-diag", "label": "neiso 26 ps diag", "date": "2026-06-23", "shorthand": "neiso-26-ps-diag", "definition": "neiso 26 ps-diag (DIAGNOSIS, not a calibration keeper). Byte-faithful re-solve of the neiso-25 fullstop keeper config (--commitment --ct-deployment --hydro-backfill-year 2024 --hydro-eia930-monthly; identical offer curves/overlays/outages, scarcity off, PS adder 0) to surface and root-cause the newly-wired C5b storage-throughput metric. FINDING: NEISO PS under-cycles (2025 model 0.59 vs EIA-930 2.08 TWh, -72%) NOT because of a storage defect but because the energy-only LP collapses the scarcity tail (model >$200 hrs 0/0/14 vs actual 72/43/290; 2025 max $258.98 vs ~$1110). PS round-trip breakeven needs an intraday price ratio >1.25 (RTE 0.80); the model's median daily ratio is 1.15, so PS clears only ~50 days/yr (~20 cycles vs the ~107 needed for 2 TWh) -- energy cap (18.6 GWh) and the $0 adder are non-binding. Step-1 measurement audit: 2023 EIA-930 PS is fully blank and 2024 begins only in Nov (14.8% coverage), so the old +47% '2024 over-cycle' was a 2-month partial scored as a full year; fixed by a coverage gate in eia_loader (storage series <50% reported -> SKIPPED). 2025 under-cycle is a real MODEL MISS handed to the scarcity/winter-gas workstream (daily AGT spot U4 / NEISO reserve scarcity pricing) -- NO storage knob added (claude.md #1/#11/#12). DETERMINATION NOT-YET (C5b storage 2025 + pre-existing C1 CC_REGULAR 2025 +2.15 TWh inherited from neiso-25). See docs/multi-iso/neiso-ps-undercycling-diagnosis-2026-06.md.", "years": [2023, 2024, 2025], "iso": "NEISO", "file": "frontend/data/backcast/runs/2026-06-23-neiso-26-ps-diag.js"}, {"id": "2026-06-23-nyiso-20-daily-coopt", "label": "nyiso 20 daily-coopt-floors", "date": "2026-06-23", "shorthand": "nyiso-20-daily-coopt", "definition": "KEEPER. The daily-Transco-gas keeper lineage (nyiso-16/17) combined for the first time with the three validated fix-#3 structural mechanisms: in-LP LOCATIONAL reserve co-optimization (--energy-reserve-coopt, 7 nested NYCA/East/SENY/NYC reserve families), the Long Island in-city self-supply floor (--nyiso-local-selfsupply, NYISO LMIC/local-reliability rule), and firm HQ/Ontario must-flow imports (--nyiso-firm-imports). Full config: --commitment --gas-monthly-actuals --gas-hub-basis-overlay --gas-hub-basis-daily --priced-interchange --energy-reserve-coopt --nyiso-local-selfsupply --nyiso-firm-imports, all 2023+2024+2025. ROOT-CAUSE of the gating winter/January downstate over-pricing: it is the gas-level artifact (the EIA-923 January receipt cost is winter-storm-inflated), NOT an import-topology bug. The measured daily Transco Z6 NY spot de-smears the within-month cold spike, collapsing the January downstate over-price from ~$98 -> $49 (load-weighted Jan residual +44 -> +5.8) and the over-generating NYC fleet from 40 -> 33.6 TWh (toward EIA-923 29). Canonical gate (verdict price_mean): 2023 +19.9% (keeper nyiso-17 +24.0%), 2024 +2.1% (keeper +7.2%, PASS), 2025 +1.2% (keeper +5.4%, PASS) -- BEATS the keeper on price every year; price_shape 2023 0.212 (keeper 0.251), 2024 0.250 (keeper 0.262). 2023 co2 now PASSES (keeper FAIL +7.7%); 2023 sysvol-gas +3.0% (keeper +5.1%); the keeper's ST_GAS +5.05 TWh fuelmix overshoot is gone. Volume bands held within ~1pp of the documented EIA-930/923 import basis floor (2024/25 gas -11/-9%). REMAINING (bounded, documented): the ~+5-7 $/MWh roughly-uniform downstate body over-price is the import/congestion residual bounded by the gas band (PJM $34 > downstate $29-38, so the deep import tranches cannot clear without breaking the EIA-923 gas band) plus the data-blocked flat-annual Iroquois-Transco summer over-level (fix #1(b), needs a paywalled monthly Iroquois Z2 series -- a winter-concentrated/multiplicative reconstruction is mean-preserving on annual gas and only trades summer for winter, so it is not a clean fix). Dec-2024 -27 and the short 2025 summer tail are the coopt-winter-eligibility follow-on (handoff #2). No fitted adders/haircuts; every input measured and forward-reproducible.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-23-nyiso-20-daily-coopt.js"}, {"id": "2026-06-23-nyiso-21-family-elig", "label": "nyiso 21 family elig", "date": "2026-06-23", "shorthand": "nyiso-21-family-elig", "definition": "Calibration run from bundle nyiso_21_family_elig.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-23-nyiso-21-family-elig.js"}, {"id": "2026-06-23-nyiso-22-gas-offer", "label": "nyiso 22 gas offer", "date": "2026-06-23", "shorthand": "nyiso-22-gas-offer", "definition": "Calibration run from bundle nyiso_22_gas_offer.", "years": [2023, 2024, 2025], "iso": "NYISO", "file": "frontend/data/backcast/runs/2026-06-23-nyiso-22-gas-offer.js"}, {"id": "2026-06-23-pjm-43-coalbit-marginal", "label": "pjm 43 coalbit marginal", "date": "2026-06-23", "shorthand": "pjm-43-coalbit-marginal", "definition": "pjm_43_coalbit_marginal: pjm_42_campdfix keeper + bituminous made marginal/price-responsive \u2014 coal_bit_passthrough_floor 0.76->1.0 (full delivered-cost bid on above-must-run tranches) AND coal_bit_dispatchable (bit per-plant CAMPD must-run floor zeroed; all capacity dispatchable, Pmin=0). PRB/lignite/waste keep take-or-pay floors. Spot-coal contract physics, not tuned to the coal/LMP residual, 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-43-coalbit-marginal.js"}, {"id": "2026-06-23-pjm-44-coalbit-sigmoid", "label": "pjm 44 coalbit sigmoid", "date": "2026-06-23", "shorthand": "pjm-44-coalbit-sigmoid", "definition": "pjm_44_coalbit_sigmoid_dispatchable: pjm_42_campdfix keeper + coal_bit_dispatchable (bit per-plant must-run floor zeroed, Pmin=0) but the gas-keyed bituminous sigmoid RETAINED (floor 0.76 -> ceil 1.32, mid 3.40), NOT flattened to full cost. Isolates dispatchability with the gas-tied offer intact: cheap gas discounts bit to hold merit, dear gas marks it up to back down, 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-44-coalbit-sigmoid.js"}, {"id": "2026-06-23-pjm-46-online-pmin", "label": "pjm 46 online pmin", "date": "2026-06-23", "shorthand": "pjm-46-online-pmin", "definition": "Coal-operations rebuild steps 1-2 on the PJM keeper: coal_takeorpay_from_data (step 1, measured EIA-923 Sch-5 sunk-fuel share) + coal_mustrun_online_pmin (step 2, coal must-run band sized to the measured online-net-MW synchronization Pmin / mustrun_online_pct ~27% cap-wtd, vs the all-hours available-CF mustrun_pct ~44%). Shrinking the cheap sub-cost band moves coal into full-cost tranches so it price-follows: vs the keeper, mean-LMP C3a now PASSes all 3 years (2025 -14.5%->-6.0%, fixing the suppression) and 2023 coal +9.2%->+0.1%; it overshoots to 2024 coal -7.9% / 2025 gas +11.4%, the next root cause (step-3 SRMC tranche + reserve co-opt). Still NOT-YET. Solved 2023-25 (serial per-year solves, merged).", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-46-online-pmin.js"}, {"id": "2026-06-23-pjm-47-ps-adder", "label": "pjm 47 ps adder", "date": "2026-06-23", "shorthand": "pjm-47-ps-adder", "definition": "pjm_47_psdiag: pjm_46 online-pmin keeper, PS DISPATCH ADDER RETIRED (PUMPED_STORAGE_DISPATCH_ADDER_BY_ISO PJM $10 -> {}; resolves to 0.0). The $10 had been fitted to a mis-measured EIA-923 PS *net* figure (round-trip loss ~2.6 TWh) read as gross discharge; true discharge throughput is ~7-10 TWh (net*RTE/(1-RTE); PJM Hydro - conventional HY). PS now arbitrages on physical RTE 0.80. All other flags = keeper. 2023 only [merged 2023-25 from parallel per-year solves]", "years": [2023, 2024, 2025], "iso": "PJM", "file": "frontend/data/backcast/runs/2026-06-23-pjm-47-ps-adder.js"}, {"id": "2026-06-23-run151-coal-prb-sigmoid", "label": "run151 coal prb sigmoid", "date": "2026-06-23", "shorthand": "run151-coal-prb-sigmoid", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-23-run151-coal-prb-sigmoid.js"}, {"id": "2026-06-23-run152-waha-haircut", "label": "run152 waha haircut", "date": "2026-06-23", "shorthand": "run152-waha-haircut", "definition": "run151 coal-keeper recipe + ERCOT zonal gas with the MEASURED contract haircut (each zone's Waha hub basis scaled by its EIA-923 Schedule-5 gas spot share; West 78% spot). This re-grounds the West/Permian delivered-gas depth on measured data instead of the -0.50 scalar floor, which was DROPPED as non-physical: the contract data shows the CT over-runners buy 100% spot Waha gas, i.e. they genuinely see ~$0 gas, so a floor overstates their fuel (CLAUDE.md #11). The haircut is the honest gas-side correction but small (trims CT_PEAKER from +82.8% to +68.6% in 2024). The remaining CT_PEAKER over-run (C1: 2024 +5.63 TWh, 2025 +4.45 TWh) is an open MODEL MISS for direction 3 (peaker cost/classification): Morgan Creek 3492 is a DFO distillate peaker mispriced on gas, and the GT peakers bid baseload on cheap gas because HR*fuel+VOM understates their low-CF startup/non-fuel cost. LMP MAE 27.9/15.2/11.3 (no regression). See docs/ercot-ct-waha-offer-floor-2026-06.md.", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-23-run152-waha-haircut.js"}, {"id": "2026-06-23-run153-waha-haircut-perplant", "label": "run153 waha haircut perplant", "date": "2026-06-23", "shorthand": "run153-waha-haircut-perplant", "definition": "run152 with the Waha contract haircut made PER-PLANT instead of zone-average: each gas unit's hub basis is scaled by ITS OWN EIA-923 spot share, so 100%-spot units (Permian Basin, Laredo) keep the full discount while a 100%-contract unit in the same zone (Ector County, share 0.0) loses it entirely. More physically faithful than the zone mean AND a better fit every year (CLAUDE.md #11/#12): CT_PEAKER 2023 -17.6% (was -25.9%), 2024 +48.7% (was +68.6%), 2025 +62.7% (was +66.8%). 358/1124 gas units haircut (mean share 0.51). LMP MAE 27.8/15.2/11.3 (no regression); C2 gas/coal family, C4 dispatch, C5a CO2 pass. The remaining CT_PEAKER over-run (2024 +4.0 TWh) is the open direction-3 MODEL MISS (the 100%-spot Permian peakers genuinely see cheap Waha gas, so the fix is peaker economics/classification, not gas price). The -0.50 floor is NOT used (dropped as non-physical). See docs/ercot-ct-waha-offer-floor-2026-06.md.", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-23-run153-waha-haircut-perplant.js"}, {"id": "2026-06-23-run154-netload-gas-laredo", "label": "run154 netload gas laredo", "date": "2026-06-23", "shorthand": "run154-netload-gas-laredo", "definition": "run134 recipe re-solved with measured 2023 AS; load-RRS-from-year=2023; storage-AS-from-year=2025; ecrs-requirement=False", "years": [2023, 2024, 2025], "iso": "ERCOT", "file": "frontend/data/backcast/runs/2026-06-23-run154-netload-gas-laredo.js"}];